// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;
import {IERC20} from '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import {IERC20Metadata} from '@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol';
import {SafeERC20} from '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import {ReentrancyGuard} from '@openzeppelin/contracts/utils/ReentrancyGuard.sol';
import {Pausable} from '@openzeppelin/contracts/utils/Pausable.sol';
import {Math} from '@openzeppelin/contracts/utils/math/Math.sol';
interface IFTI {
    function inject(uint256,bool) external;
    function autoBuy(address,uint256,uint256,uint256) external returns(uint256);
    function price() external view returns(uint256);
    function priceMultiplier() external view returns(uint256);
    function quoteBuy(uint256) external view returns(uint256);
}
library Calendar {
    function leap(uint256 y) internal pure returns(bool){return y%4==0&&(y%100!=0||y%400==0);}
    function month(uint256 timestamp) internal pure returns(uint256 key,uint256 end){
        uint256 daysLeft=timestamp/1 days;uint256 y=1970;uint256 start;
        // Deployment range is deliberately bounded. No user-provided calendar input.
        require(timestamp<4102444800,'calendar range');
        while(daysLeft>=(leap(y)?366:365)){uint256 n=leap(y)?366:365;daysLeft-=n;start+=n;y++;}
        uint256[12] memory lengths=[uint256(31),28,31,30,31,30,31,31,30,31,30,31];if(leap(y))lengths[1]=29;
        uint256 m;while(daysLeft>=lengths[m]){daysLeft-=lengths[m];start+=lengths[m];m++;}
        key=y*12+m;end=(start+lengths[m])*1 days;
    }
    function endOf(uint256 key) internal pure returns(uint256){uint256 year=key/12;uint256 m=key%12;require(year>=1970&&year<2100,'calendar range');uint256 d;for(uint256 y=1970;y<year;y++)d+=leap(y)?366:365;uint256[12] memory a=[uint256(31),28,31,30,31,30,31,31,30,31,30,31];if(leap(year))a[1]=29;for(uint256 i;i<=m;i++)d+=a[i];return d*1 days;}
}
/// @notice Experimental pull-payment plan; processing is bounded, all work is permissionless.
contract BinaryPlan is ReentrancyGuard,Pausable {
    using SafeERC20 for IERC20;
    uint256 public constant UNIT=100e18;
    uint256 public constant MAX_BATCH=100;
    IERC20 public immutable usd;
    IFTI public immutable token;
    address public immutable governance;
    address public immutable guardian;
    address public immutable development;
    struct Member {address parent;address left;address right;uint256 units;uint256 carryL;uint256 carryR;uint256 lifetimeL;uint256 lifetimeR;uint8 rank;bool exists;bool autoEnabled;uint256 maxAutoPrice;}
    mapping(address=>Member) public members;
    /// @notice Gross manual FTI purchases authorized by this binary plan; sales never restore quota.
    mapping(address=>uint256) public tokenBuySpent;
    /// @notice PROVISIONAL: rank counts capped points with an actual funded reward allocation,
    ///         not raw matched volume or later cash withdrawal. Claims never add rank points.
    mapping(address=>uint256) public cumulativePaidRankPoints;
    address[] public memberList;
    mapping(address=>uint64[4]) public rankReachedAt;
    struct Job {address child;address ancestor;uint256 units;}
    Job[] public jobs;uint256 public jobCursor;
    uint256 public epoch=1;uint256 public epochEnd;uint256 public lastClosedAt;
    uint256 public epochUnits;uint256 public unitsSinceSettlement;uint256 public pointPool;
    uint8 public protectionLevel;uint8 public frozenLevel;
    uint8 public phase; // 0 deposits, 1 matching, 2 allocation
    uint256 public cursor;uint256 public frozenMembers;uint256 public totalPaidPoints;uint256 public pointValue;uint256 public frozenPool;uint256 public allocated;
    mapping(uint256=>mapping(address=>uint256)) public paidPoints;
    mapping(uint256=>mapping(address=>bool)) public autoSnapshot;
    mapping(uint256=>mapping(address=>bool)) public settled;
    mapping(address=>uint256) public pendingReward;
    mapping(address=>uint256) public pendingAuto;
    uint256 public totalPending;uint256 public totalAuto;
    uint256 public builderAccounted;
    mapping(uint256=>uint256[4]) public monthFunding;
    uint256[4] public builderCarry;
    mapping(address=>bool[4]) public builderClaimed;
    uint256 public nextBuilderMonth;uint8 public monthPhase;uint256 public monthCursor;uint256 public monthMembers;
    uint256[4] public monthBalances;uint256[4] public monthEligible;uint256[4] public monthPay;
    event Registered(address indexed wallet,address indexed sponsor,uint256 units);
    event UnitsAdded(address indexed wallet,uint256 units);
    event EpochClosed(uint256 indexed epoch,uint256 pool,uint256 points,uint256 pointValue,uint8 nextProtection);
    event RewardAllocated(uint256 indexed epoch,address indexed wallet,uint256 cash,uint256 automatic);
    event RankPointsAllocated(address indexed wallet,uint256 points,uint256 cumulativePoints,uint8 rank);
    event PointPoolRoundingAllocated(uint256 indexed epoch,uint256 amount);
    event Claimed(address indexed wallet,uint256 amount);
    event BuilderMonthClosed(uint256 indexed month);
    event AutoExecuted(address indexed wallet,uint256 usdIn,uint256 tokens);
    event TokenBuyAuthorized(address indexed wallet,uint256 usdIn,uint256 cumulativeSpent);
    constructor(address stable,address fti,address gov,address emergency,address dev,address[31] memory genesis){
        require(IERC20Metadata(stable).decimals()==18,'requires 18 decimal USD');
        require(fti.code.length>0&&gov!=address(0)&&emergency!=address(0)&&dev!=address(0),'addresses');
        usd=IERC20(stable);token=IFTI(fti);governance=gov;guardian=emergency;development=dev;
        epochEnd=(block.timestamp/1 hours+1)*1 hours;(nextBuilderMonth,)=Calendar.month(block.timestamp);
        for(uint256 i;i<31;i++){
            address who=genesis[i];require(who!=address(0)&&!members[who].exists,'genesis');
            members[who].exists=true;memberList.push(who);
            if(i>0){address parent=genesis[(i-1)/2];members[who].parent=parent;if(i%2==1)members[parent].left=who;else members[parent].right=who;}
        }
        usd.forceApprove(fti,type(uint256).max);
    }
    function memberCount() external view returns(uint256){return memberList.length;}
    function jobCount() external view returns(uint256){return jobs.length;}
    function unitsOf(address who) external view returns(uint256){return members[who].units;}
    function rankOf(address who) external view returns(uint8){return members[who].rank;}
    function registered(address who) external view returns(bool){return members[who].exists;}
    /// @notice Cumulative gross-buy capacity uses current permanent rank and all paid units.
    ///         Builders alone receive the token's latched 10x-price milestone multiplier.
    ///         Rank/top-up/milestone increases grant only extra capacity; spent is never reset.
    function tokenBuyLimit(address who) public view returns(uint256){
        Member storage m=members[who];
        uint256[5] memory limits=[uint256(500),600,700,800,1000];
        uint256 multiplier=m.rank==0?1:token.priceMultiplier();
        return m.units*limits[m.rank]*1e18*multiplier;
    }
    function remainingTokenBuyAllowance(address who) public view returns(uint256){
        uint256 limit=tokenBuyLimit(who);uint256 spent=tokenBuySpent[who];
        return limit>spent?limit-spent:0;
    }
    /// @dev The bound token consumes permission atomically with the manual purchase. Reward auto-buys do not call this.
    function authorizeTokenBuy(address who,uint256 amount) external nonReentrant {
        require(msg.sender==address(token),'token only');
        require(members[who].units>0&&amount>0,'buy input');
        require(amount<=remainingTokenBuyAllowance(who),'allowance');
        tokenBuySpent[who]+=amount;
        emit TokenBuyAuthorized(who,amount,tokenBuySpent[who]);
    }
    function pause() external {require(msg.sender==guardian||msg.sender==governance,'role');_pause();}
    function unpause() external {require(msg.sender==governance,'governance');_unpause();}
    function register(address sponsor,uint256 units) external nonReentrant whenNotPaused {
        require(!members[msg.sender].exists&&members[sponsor].exists&&sponsor!=msg.sender,'registration');
        Member storage p=members[sponsor];require(p.right==address(0),'sponsor full');
        members[msg.sender].exists=true;members[msg.sender].parent=sponsor;memberList.push(msg.sender);
        if(p.left==address(0))p.left=msg.sender;else p.right=msg.sender;
        _fund(msg.sender,units,true);emit Registered(msg.sender,sponsor,units);
    }
    function addUnits(uint256 units) external nonReentrant whenNotPaused {require(members[msg.sender].exists,'member');_fund(msg.sender,units,false);emit UnitsAdded(msg.sender,units);}
    function _fund(address who,uint256 units,bool newWallet) private {
        require(phase==0&&block.timestamp<epochEnd,'settlement required');require(units>0&&units<=1000000,'unit range');
        _backed();uint256 amount=units*UNIT;uint256 beforeBal=usd.balanceOf(address(this));uint256 beforeUser=usd.balanceOf(who);
        usd.safeTransferFrom(who,address(this),amount);require(usd.balanceOf(address(this))-beforeBal==amount&&beforeUser-usd.balanceOf(who)==amount,'unsupported USD');
        members[who].units+=units;epochUnits+=units;unitsSinceSettlement+=units;pointPool+=units*90e18;
        pendingReward[development]+=units*1e18;totalPending+=units*1e18;
        (uint256 monthKey,)=Calendar.month(block.timestamp);uint256[4] memory portions=[uint256(16e17),12e17,8e17,4e17];
        for(uint256 i;i<4;i++)monthFunding[monthKey][i]+=units*portions[i];builderAccounted+=units*4e18;
        address parent=members[who].parent;if(parent!=address(0))jobs.push(Job(who,parent,units));
        uint256 beforeInject=usd.balanceOf(address(this));uint256 beforeToken=usd.balanceOf(address(token));
        token.inject(units*5e18,newWallet);
        require(beforeInject-usd.balanceOf(address(this))==units*5e18&&usd.balanceOf(address(token))-beforeToken==units*5e18,'unsupported USD');
        _backed();
    }
    function processVolume(uint256 steps) external nonReentrant {require(phase==0&&steps>0&&steps<=MAX_BATCH,'batch');
        for(uint256 i;i<steps&&jobCursor<jobs.length;i++){
            Job storage j=jobs[jobCursor];Member storage p=members[j.ancestor];
            if(p.left==j.child){p.carryL+=j.units;p.lifetimeL+=j.units;}else{require(p.right==j.child,'tree');p.carryR+=j.units;p.lifetimeR+=j.units;}
            j.child=j.ancestor;j.ancestor=p.parent;if(j.ancestor==address(0))jobCursor++;
        }
    }
    function cap(uint8 rank,uint8 level) public pure returns(uint256){require(rank<5&&level<4,'cap');uint8[5][4] memory c=[[5,10,15,20,25],[5,10,12,16,20],[5,10,10,12,15],[5,10,10,10,10]];return c[level][rank];}
    function beginEpochClose() external nonReentrant {
        require(phase==0&&block.timestamp>=epochEnd&&jobCursor==jobs.length,'not ready');_backed();
        // Gate on this hour's paid registration units; old cash carries, old units do not qualify.
        if(epochUnits<5){_nextEpoch();return;}
        frozenMembers=memberList.length;frozenLevel=protectionLevel;cursor=0;totalPaidPoints=0;allocated=0;frozenPool=pointPool;pointValue=0;phase=1;
    }
    function processEpoch(uint256 batch) external nonReentrant {
        require(batch>0&&batch<=MAX_BATCH&&phase>0,'batch');_backed();
        uint256 end=cursor+batch;if(end>frozenMembers)end=frozenMembers;
        if(phase==1){
            for(;cursor<end;cursor++){
                address who=memberList[cursor];Member storage m=members[who];uint256 raw=m.carryL<m.carryR?m.carryL:m.carryR;
                if(m.units>0){uint256 c=cap(m.rank,frozenLevel);uint256 paid=raw<c?raw:c;paidPoints[epoch][who]=paid;totalPaidPoints+=paid;autoSnapshot[epoch][who]=m.autoEnabled&&m.rank>0;}
                // Inactive Genesis positions retain volume; no unfunded reward privileges.
                if(m.units>0){m.carryL-=raw;m.carryR-=raw;}
            }
            if(cursor==frozenMembers){
                // PROVISIONAL: preserve an unmatched global pool until ownership is approved.
                // No eligible points means no distribution and no rounding allocation.
                if(totalPaidPoints==0){emit EpochClosed(epoch,frozenPool,0,0,protectionLevel);_nextEpoch();return;}
                pointValue=frozenPool/totalPaidPoints;phase=2;cursor=0;
            }
        }else{
            for(;cursor<end;cursor++){
                address who=memberList[cursor];require(!settled[epoch][who],'settled');settled[epoch][who]=true;
                // $20 is a protection target for the NEXT epoch, never a payout ceiling or gate.
                uint256 points=paidPoints[epoch][who];uint256 reward=Math.mulDiv(frozenPool,points,totalPaidPoints);
                uint256 automatic=autoSnapshot[epoch][who]?reward*5/100:0;
                pendingReward[who]+=reward-automatic;totalPending+=reward-automatic;pendingAuto[who]+=automatic;totalAuto+=automatic;allocated+=reward;pointPool-=reward;
                emit RewardAllocated(epoch,who,reward-automatic,automatic);
                // The current reward and auto split were fixed under the OLD rank.
                // Only a successfully funded allocation can advance permanent rank.
                if(reward>0){
                    uint256 cumulative=cumulativePaidRankPoints[who]+points;cumulativePaidRankPoints[who]=cumulative;
                    Member storage m=members[who];uint256[4] memory thresholds=[uint256(100),200,500,1000];
                    for(uint256 r=m.rank;r<4;r++){if(cumulative>=thresholds[r]){m.rank=uint8(r+1);rankReachedAt[who][r]=uint64(epochEnd);}else break;}
                    emit RankPointsAllocated(who,points,cumulative,m.rank);
                }
            }
            if(cursor==frozenMembers){
                // Each wallet receives floor(pool * points / totalPoints). Only the exact
                // sum-of-floors residual goes to development; it is not a fee or reserve.
                uint256 rounding=frozenPool-allocated;
                pointPool-=rounding;pendingReward[development]+=rounding;totalPending+=rounding;
                if(rounding>0)emit PointPoolRoundingAllocated(epoch,rounding);
                if(frozenPool<20e18*totalPaidPoints&&protectionLevel<3)protectionLevel++;
                else if(frozenPool>20e18*totalPaidPoints&&protectionLevel>0)protectionLevel--;
                unitsSinceSettlement=0;emit EpochClosed(epoch,frozenPool,totalPaidPoints,pointValue,protectionLevel);_nextEpoch();
            }
        }
        _backed();
    }
    function _nextEpoch() private {lastClosedAt=(block.timestamp/1 hours)*1 hours;epoch++;epochEnd=(block.timestamp/1 hours+1)*1 hours;epochUnits=0;phase=0;cursor=0;}
    function setAutoBuy(bool enabled,uint256 maxPrice) external nonReentrant {require(phase==0,'settings frozen');require(members[msg.sender].exists,'member');require(!enabled||maxPrice>0,'price limit');members[msg.sender].autoEnabled=enabled;members[msg.sender].maxAutoPrice=maxPrice;}
    function executeAuto(address who,uint256 amount) external nonReentrant {
        _backed();
        require(amount>0&&amount<=pendingAuto[who],'amount');
        require(members[who].autoEnabled,'auto disabled');
        // A keeper may not split someone else's reward into dust-sized lock tranches.
        // The beneficiary can still request a deliberate partial purchase.
        require(msg.sender==who||amount==pendingAuto[who],'partial auto owner only');
        uint256 maxPrice=members[who].maxAutoPrice;
        require(maxPrice>0&&token.price()<=maxPrice,'auto price limit');
        uint256 minimum=token.quoteBuy(amount);require(minimum>0,'dust');
        // Max price is the total USD paid per FTI received, including fees/curve impact.
        require(minimum>=Math.mulDiv(amount,1e18,maxPrice,Math.Rounding.Ceil),'auto execution price');
        pendingAuto[who]-=amount;totalAuto-=amount;
        uint256 beforeBal=usd.balanceOf(address(this));uint256 beforeToken=usd.balanceOf(address(token));
        uint256 minted=token.autoBuy(who,amount,minimum,block.timestamp);
        require(beforeBal-usd.balanceOf(address(this))==amount&&usd.balanceOf(address(token))-beforeToken==amount,'unsupported USD');
        _backed();emit AutoExecuted(who,amount,minted);
    }
    function releaseAutoToCash() external nonReentrant {uint256 amount=pendingAuto[msg.sender];pendingAuto[msg.sender]=0;totalAuto-=amount;pendingReward[msg.sender]+=amount;totalPending+=amount;}
    function claim() external nonReentrant {_backed();uint256 amount=pendingReward[msg.sender];require(amount>0,'no reward');pendingReward[msg.sender]=0;totalPending-=amount;uint256 beforeBal=usd.balanceOf(address(this));uint256 beforeUser=usd.balanceOf(msg.sender);usd.safeTransfer(msg.sender,amount);require(beforeBal-usd.balanceOf(address(this))==amount&&usd.balanceOf(msg.sender)-beforeUser==amount,'unsupported USD');_backed();emit Claimed(msg.sender,amount);}
    function beginBuilderMonth() external nonReentrant {
        uint256 end=Calendar.endOf(nextBuilderMonth);require(monthPhase==0&&block.timestamp>=end&&lastClosedAt>=end,'month not ready');
        monthMembers=memberList.length;monthCursor=0;monthPhase=1;
        for(uint256 p;p<4;p++){monthBalances[p]=builderCarry[p]+monthFunding[nextBuilderMonth][p];monthFunding[nextBuilderMonth][p]=0;builderCarry[p]=0;monthEligible[p]=0;monthPay[p]=0;}
    }
    function _eligible(address who,uint256 p,uint256 end) private view returns(bool){uint256 at=rankReachedAt[who][p];return at>0&&at<=end&&!builderClaimed[who][p];}
    function processBuilderMonth(uint256 batch) external nonReentrant {
        require(monthPhase>0&&batch>0&&batch<=MAX_BATCH,'batch');uint256 end=monthCursor+batch;if(end>monthMembers)end=monthMembers;uint256 cutoff=Calendar.endOf(nextBuilderMonth);
        if(monthPhase==1){
            for(;monthCursor<end;monthCursor++)for(uint256 p;p<4;p++)if(_eligible(memberList[monthCursor],p,cutoff))monthEligible[p]++;
            if(monthCursor==monthMembers){for(uint256 p;p<4;p++){uint256 count=monthEligible[p];if(count>0){uint256 equal=monthBalances[p]/count;uint256 limit=monthBalances[p]/5;monthPay[p]=equal<limit?equal:limit;}builderCarry[p]=monthBalances[p]-monthPay[p]*count;}monthCursor=0;monthPhase=2;}
        }else{
            for(;monthCursor<end;monthCursor++){address who=memberList[monthCursor];for(uint256 p;p<4;p++)if(_eligible(who,p,cutoff)&&monthPay[p]>0){builderClaimed[who][p]=true;pendingReward[who]+=monthPay[p];totalPending+=monthPay[p];builderAccounted-=monthPay[p];}}
            if(monthCursor==monthMembers){emit BuilderMonthClosed(nextBuilderMonth);nextBuilderMonth++;monthPhase=0;monthCursor=0;}
        }
    }
    function _backed() private view {require(usd.balanceOf(address(this))>=pointPool+builderAccounted+totalPending+totalAuto,'reserve deficit');}
    function accounting() external view returns(uint256 actual,uint256 accounted){return(usd.balanceOf(address(this)),pointPool+builderAccounted+totalPending+totalAuto);}
    function rescue(address asset,address to,uint256 amount) external nonReentrant {require(msg.sender==governance&&asset!=address(usd)&&asset!=address(token),'protected');IERC20(asset).safeTransfer(to,amount);}
}

FTIReserveToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {ERC20} from '@openzeppelin/contracts/token/ERC20/ERC20.sol';
import {IERC20} from '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import {IERC20Metadata} from '@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol';
import {SafeERC20} from '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import {ReentrancyGuard} from '@openzeppelin/contracts/utils/ReentrancyGuard.sol';
import {Pausable} from '@openzeppelin/contracts/utils/Pausable.sol';
import {Math} from '@openzeppelin/contracts/utils/math/Math.sol';

interface IReserveMembership {
    function unitsOf(address) external view returns (uint256);
    function tokenBuyLimit(address) external view returns (uint256);
    function remainingTokenBuyAllowance(address) external view returns (uint256);
    function tokenBuySpent(address) external view returns (uint256);
    function authorizeTokenBuy(address,uint256) external;
}

/// @notice LOCAL size-fee review: approved $500/5% threshold; 7% curve remains provisional.
/// @dev Starts with zero FTI. Binary support NEVER mints FTI. Zero-supply
///      support is held in the price-protection fund, outside redeemable reserve.
///      No fund spending, release, trigger or governance path is implemented.
///      Ordinary buys/sells have a 3% base fee. Only the current trade's gross
///      value above BOTH $500 and 5% of pretrade live reserve incurs the surcharge.
///      No pressure snapshot, timer, wallet history or previous trade is charged.
///      Buys retain all cash; net-of-fee value mints at the pretrade price.
///      Positive wallet transfers burn 3%; normal partial sales burn the sold
///      tokens and retain their fee in reserve. Full final and emergency exits
///      are fee-free. Protected fund cash and donations are not sale proceeds.
///      There are no personal waiting locks; restart remains review-gated.
contract FTIReserveToken is ERC20, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    uint256 public constant WAD = 1e18;
    uint256 public constant INITIAL_PRICE = 1e17;
    uint256 public constant FEE_BPS = 300;
    uint256 public constant TRANSFER_BURN_BPS = 300;
    uint256 public constant RETAINED_BPS = 300;
    // Threshold correction approved for local review; 7% coefficient remains provisional.
    uint256 public constant LARGE_TRADE_MIN_USD = 500e18;
    uint256 public constant LARGE_TRADE_THRESHOLD_BPS = 500;
    uint256 public constant MAX_SIZE_FEE_BPS = 700;
    uint256 public constant MAX_SELL_FEE_BPS = FEE_BPS+MAX_SIZE_FEE_BPS;
    uint256 public constant MAX_BUY_FEE_BPS = FEE_BPS+MAX_SIZE_FEE_BPS;
    // Explicitly disabled pressure compatibility getters. No temporal fee exists.
    bool public constant SELL_PRESSURE_ACTIVE = false;
    uint256 public constant MAX_PRESSURE_FEE_BPS = 0;
    uint256 public constant PRESSURE_HALF_LIFE = 0;
    uint256 public constant PRESSURE_DECAY_PER_SECOND = 0;
    uint256 public constant MAX_PRESSURE_DECAY_SECONDS = 0;
    // Deprecated compatibility getters: zero means DISABLED, never a 0% sale cap.
    bool public constant SELL_CAPS_ACTIVE = false;
    uint256 public constant MAX_SINGLE_SELL_BPS = 0;
    uint256 public constant MAX_HOURLY_GROSS_SELL_BPS = 0;
    uint256 public constant MAX_RESERVE = 1e30;
    uint256 public constant MAX_SUPPLY = 1e36;
    uint256 public constant MIN_MINT = 1e6;
    uint256 public constant CAP_REFERENCE_SUPPLY = 1000000e18;
    bytes32 public constant pricingModel = 'REAL_RESERVE_SIZE_PROPOSAL';

    IERC20 public immutable usd;
    address public immutable governance;
    address public immutable guardian;
    address public immutable deployer;
    IReserveMembership public binary;

    uint256 public reserve; // Redeemable backing of circulating FTI only.
    uint256 public priceProtectionFund; // Protected zero-supply cash; spending policy remains unapproved.
    uint256 public constant launchPrice = INITIAL_PRICE; // Fixed milestone anchor, not the first buy quote.
    uint256 public milestonePrice = INITIAL_PRICE*10;
    uint256 public ath; // status/compatibility metric, not a guaranteed liquidation price
    uint256 public walletClock; // registration metric only; never used for token locks
    uint256 public priceMultiplier = 1;
    uint256 public cumulativeBuy;
    uint256 public cumulativeSell;

    struct Lock {uint256 amount;uint64 clock;uint64 deadline;}

    // Deprecated compatibility counters; no windows or capacity checks are active.
    uint256 public sellWindowStart;
    uint256 public sellWindowStartReserve;
    uint256 public sellWindowGross;
    bool public emergencyExit;
    bool public lifecycleClosed; // Restart remains review-gated pending explicit approval.
    uint256 public referencePrice = INITIAL_PRICE;
    uint256 public constant pressureWad = 0; // Deprecated; pressure is disabled.
    uint256 public constant lastPartialSellAt = 0; // Deprecated; no fee timer exists.


    event Bound(address indexed binary);
    event Bought(address indexed wallet,uint256 usdIn,uint256 userTokens,bool automatic);
    event Sold(address indexed wallet,uint256 tokens,uint256 usdOut,uint256 baseFeeBps,uint256 impactBps);
    event ReserveInjected(uint256 amount);
    event ReserveQuarantined(uint256 amount,uint256 totalUnallocated);
    event MultiplierUpdated(uint256 multiplier,uint256 nextMilestone);
    event ReservePriceUpdated(uint256 reserve,uint256 shares,uint256 price);
    event EmergencyExitActivated(address indexed caller);
    event EmergencyExitDeactivated();
    event LifecycleClosed(uint256 residualReserve,uint256 referencePrice,bool emergency);
    event SellWindowReset(uint256 indexed start,uint256 reserveSnapshot);
    // Deprecated compatibility event; never emitted by this proposal.
    event SellPressureUpdated(uint256 pressureWad,uint256 timestamp);

    modifier onlyBinary(){require(msg.sender==address(binary),'binary only');_;}

    constructor(address stable,address gov,address emergency)
        ERC20('FTI Protocol','FTI')
    {
        require(stable.code.length>0&&gov!=address(0)&&emergency!=address(0),'addresses');
        require(IERC20Metadata(stable).decimals()==18,'requires 18 decimal USD');
        usd=IERC20(stable);
        governance=gov;
        guardian=emergency;
        deployer=msg.sender;
    }

    function bind(address c1) external {
        require(msg.sender==deployer&&address(binary)==address(0)&&c1.code.length>0,'bind');
        binary=IReserveMembership(c1);
        emit Bound(c1);
    }

    /// @dev Pause blocks buys and wallet-to-wallet transfers. Sells remain open.
    function pause() external {require(msg.sender==guardian||msg.sender==governance,'role');_pause();}
    function unpause() external {require(msg.sender==governance,'governance');_unpause();}

    /// @notice 7-wallet council (guardian) may activate after its on-chain threshold vote.
    ///         This does not transfer reserve to administrators; it makes the protocol redemption-only.
    function activateEmergencyExit() external {
        require(msg.sender==guardian||msg.sender==governance,'role');
        emergencyExit=true;
        if(!paused())_pause();
        emit EmergencyExitActivated(msg.sender);
    }
    function deactivateEmergencyExit() external {
        require(msg.sender==governance,'governance');
        emergencyExit=false;
        if(paused())_unpause();
        emit EmergencyExitDeactivated();
    }

    function circulatingSupply() public view returns(uint256){return totalSupply();}
    /// @notice At zero supply this is a historical/bootstrap reference, not redeemable value.
    function price() public view returns(uint256){
        return totalSupply()==0?referencePrice:Math.mulDiv(reserve,WAD,totalSupply());
    }
    function buybackFund() external pure returns(uint256){return 0;}
    function floorFund() external pure returns(uint256){return 0;}
    function anchorSupply() external pure returns(uint256){return 0;}
    /// @notice Base fee only. Use buyFeeQuote(amount) for the actual fee amount.
    function buyFeeBps() external pure returns(uint256){return FEE_BPS;}
    /// @notice Deprecated name for protected price-protection-fund cash.
    function unallocatedReserve() external view returns(uint256){return priceProtectionFund;}

    /// @notice Cumulative manual-buy authorization is owned by the binary contract.
    ///         Each paid unit grants its rank-based capacity; selling never restores quota.
    function buyLimit(address who) public view returns(uint256){return binary.tokenBuyLimit(who);}
    function remainingAllowance(address who) public view returns(uint256){return binary.remainingTokenBuyAllowance(who);}
    function lifetimeManualBuys(address who) external view returns(uint256){return binary.tokenBuySpent(who);}

    function _fee(uint256 amount,uint256 bps) private pure returns(uint256){
        return Math.mulDiv(amount,bps,10000,Math.Rounding.Ceil);
    }
    /// @dev T = max(500 USD, R/20), keeping fractional USD atoms exact.
    ///      With thresholdTimes20=max(20*500e18,R), X=max(20V-thresholdTimes20,0).
    ///      B=X/20 and F=ceil((300*400*V^2+700*X^2)/(10000*400*V)).
    ///      One combined rational amount receives ONE ceil. V,R<=1e30 bounds
    ///      the numerator by 4e65 (<2^256) and denominator by 4e36.
    ///      R=0/S=0 retains the existing base-only bootstrap review exception.
    function _sizeExcessTimes20(uint256 value) private view returns(uint256){
        uint256 thresholdTimes20=Math.max(LARGE_TRADE_MIN_USD*20,reserve);
        return value*20>thresholdTimes20?value*20-thresholdTimes20:0;
    }
    function _tradeFee(uint256 value) private view returns(uint256){
        require(value<=MAX_RESERVE&&reserve<=MAX_RESERVE,'fee range');
        if(value==0)return 0;
        if(totalSupply()==0||reserve==0)return _fee(value,FEE_BPS);
        uint256 excessTimes20=_sizeExcessTimes20(value);
        if(excessTimes20==0)return _fee(value,FEE_BPS);
        uint256 numerator=FEE_BPS*400*value*value+MAX_SIZE_FEE_BPS*excessTimes20*excessTimes20;
        uint256 denominator=10000*400*value;
        return Math.ceilDiv(numerator,denominator);
    }

    /// @notice Amount-specific total fee in USD atoms and net minting value.
    /// @dev All amount is retained in reserve; only netAssets mints FTI.
    ///      Zero netAssets is a dust quote and cannot execute as a buy.
    function buyFeeQuote(uint256 amount) public view returns(uint256 feeAmount,uint256 netAssets){
        require(amount>0&&amount<=MAX_RESERVE,'amount');
        feeAmount=_tradeFee(amount);
        netAssets=amount-feeAmount;
    }

    /// @notice Only net-of-fee user value mints tokens. Restart after final redemption is disabled.
    function quoteBuy(uint256 amount) public view returns(uint256){
        require(!lifecycleClosed,'restart policy pending');
        (,uint256 userAssets)=buyFeeQuote(amount);
        require(userAssets>0,'dust');
        uint256 prePrice=price();
        require(prePrice>0,'reserve');
        return Math.mulDiv(userAssets,WAD,prePrice);
    }

    /// @notice Deprecated compatibility views: temporal/global pressure is disabled.
    function currentSellPressure() public pure returns(uint256){return 0;}
    function previewSellPressure(uint256 tokens) public view returns(uint256){
        require(tokens<=totalSupply(),'supply');
        return 0;
    }

    /// @notice Truncated indicative average surcharge in bps, NOT a fee calculator.
    /// @dev Use sellFeeQuote for the exact, once-rounded USD fee. A sub-bps size
    ///      surcharge can exist even when this compatibility display returns zero.
    function sellImpactBps(uint256 tokens) public view returns(uint256){
        uint256 supply=totalSupply();
        require(tokens<=supply,'supply');
        if(tokens==0||tokens==supply||emergencyExit||reserve==0)return 0;
        uint256 gross=Math.mulDiv(tokens,reserve,supply);
        require(gross<=MAX_RESERVE&&reserve<=MAX_RESERVE,'fee range');
        uint256 excessTimes20=_sizeExcessTimes20(gross);
        if(excessTimes20==0)return 0;
        return Math.mulDiv(MAX_SIZE_FEE_BPS,excessTimes20*excessTimes20,400*gross*gross);
    }

    /// @notice Exact USD fee, payout and gross claim. Full and emergency exits pay no fee.
    function sellFeeQuote(uint256 tokens) public view returns(uint256 feeAmount,uint256 payout,uint256 gross){
        uint256 supply=totalSupply();
        require(tokens<=supply,'supply');
        if(tokens==0||supply==0)return(0,0,0);
        gross=Math.mulDiv(tokens,reserve,supply);
        if(!emergencyExit&&tokens!=supply)feeAmount=_tradeFee(gross);
        require(gross>feeAmount,'dust');
        payout=gross-feeAmount;
    }

    /// @notice Legacy quote shape; feeBps is truncated indicative average only.
    /// @dev Never reconstruct the fee from feeBps. sellFeeQuote exposes exact USD.
    function quoteSell(uint256 tokens) public view returns(uint256 payout,uint256 feeBps,uint256 gross){
        (,payout,gross)=sellFeeQuote(tokens);
        feeBps=emergencyExit||(tokens>0&&tokens==totalSupply())?0:FEE_BPS+sellImpactBps(tokens);
    }

    /// @notice Binary funding never creates FTI. Only funding received while supply
    ///         is positive becomes redeemable backing. Zero-supply cash remains
    ///         in the price-protection fund, including after closure and later buys.
    function inject(uint256 amount,bool newWallet) external onlyBinary nonReentrant {
        require(amount>0&&amount<=MAX_RESERVE&&reserve+priceProtectionFund+amount<=MAX_RESERVE,'reserve range');
        _receive(msg.sender,amount);
        if(totalSupply()==0){
            priceProtectionFund+=amount;
            emit ReserveQuarantined(amount,priceProtectionFund);
        }else reserve+=amount;
        if(newWallet)walletClock++;
        _backed();
        _syncMilestone();
        _recordPrice();
        emit ReserveInjected(amount);
    }

    function buy(uint256 amount,uint256 minTokens,uint256 deadline)
        external nonReentrant whenNotPaused returns(uint256)
    {
        require(!emergencyExit,'redemption only');
        return _buy(msg.sender,msg.sender,amount,minTokens,deadline,false);
    }
    function autoBuy(address who,uint256 amount,uint256 minTokens,uint256 deadline)
        external onlyBinary nonReentrant whenNotPaused returns(uint256)
    {
        require(!emergencyExit,'redemption only');
        return _buy(msg.sender,who,amount,minTokens,deadline,true);
    }

    function _buy(address payer,address who,uint256 amount,uint256 minTokens,uint256 deadline,bool automatic)
        private returns(uint256 minted)
    {
        require(!lifecycleClosed,'restart policy pending');
        require(block.timestamp<=deadline&&amount>0&&binary.unitsOf(who)>0,'buy input');

        uint256 previousR=reserve;
        uint256 previousS=totalSupply();
        minted=quoteBuy(amount);
        require(minted>=MIN_MINT&&minted>=minTokens,'slippage/dust');
        require(reserve+priceProtectionFund+amount<=MAX_RESERVE&&previousS+minted<=MAX_SUPPLY,'range');

        // The binary consumes manual authorization before collateral moves. Any later
        // failure reverts both the quota and token state in the same transaction.
        if(!automatic)binary.authorizeTokenBuy(who,amount);
        _receive(payer,amount);
        reserve+=amount;

        _mint(who,minted);
        cumulativeBuy+=amount;

        if(previousS>0)_requireGrowth(previousR,previousS);
        else require(price()>referencePrice,'price step too small');
        _syncMilestone();
        _recordPrice();
        emit Bought(who,amount,minted,automatic);
    }

    function sell(uint256 tokens,uint256 minUSD,uint256 deadline)
        external nonReentrant returns(uint256 payout)
    {
        require(block.timestamp<=deadline&&tokens>0&&tokens<=balanceOf(msg.sender),'sell input');
        uint256 supply=circulatingSupply();
        bool finalRedemption=tokens==supply;

        uint256 gross;uint256 totalFeeBps;
        (payout,totalFeeBps,gross)=quoteSell(tokens);
        require(payout>0&&payout>=minUSD&&payout<=reserve,'slippage/dust');

        uint256 previousR=reserve;
        uint256 previousS=totalSupply();
        uint256 previousPrice=price();

        reserve-=payout;
        cumulativeSell+=gross;
        _burn(msg.sender,tokens);

        if(finalRedemption){
            // No live R/S exists at zero supply. Preserve the last real quote without
            // fabricating a price step. Exact full redemption leaves no redeemable
            // fee residue; quarantined cash and raw donations remain protected.
            // The binary-owned lifetime manual-buy quota is never reset.
            referencePrice=previousPrice;
            lifecycleClosed=true;
            _backed();
            emit LifecycleClosed(reserve,referencePrice,emergencyExit);
        }else if(emergencyExit)_backed();
        else _requireGrowth(previousR,previousS);
        _syncMilestone();
        _recordPrice();

        uint256 beforePool=usd.balanceOf(address(this));
        uint256 beforeUser=usd.balanceOf(msg.sender);
        usd.safeTransfer(msg.sender,payout);
        require(beforePool-usd.balanceOf(address(this))==payout&&
            usd.balanceOf(msg.sender)-beforeUser==payout,'unsupported USD');
        _backed();
        emit Sold(msg.sender,tokens,payout,totalFeeBps==0?0:FEE_BPS,totalFeeBps>FEE_BPS?totalFeeBps-FEE_BPS:0);
    }

    function _receive(address payer,uint256 amount) private {
        _backed();
        uint256 beforeBalance=usd.balanceOf(address(this));
        uint256 beforePayer=usd.balanceOf(payer);
        usd.safeTransferFrom(payer,address(this),amount);
        require(usd.balanceOf(address(this))-beforeBalance==amount&&
            beforePayer-usd.balanceOf(payer)==amount,'unsupported USD');
    }

    function _backed() private view {require(usd.balanceOf(address(this))>=reserve+priceProtectionFund,'reserve deficit');}
    function _requireGrowth(uint256 oldR,uint256 oldS) private view {
        require(oldS>0&&totalSupply()>0,'supply');
        require(reserve*oldS>oldR*totalSupply(),'price must increase');
        // Strict exact growth alone may be invisible after WAD rounding. Reject
        // a trade too small to advance the actual displayed reserve/share price.
        require(price()>Math.mulDiv(oldR,WAD,oldS),'price step too small');
        _backed();
    }
    function _recordPrice() private {
        uint256 p=price();
        if(p>ath)ath=p;
        emit ReservePriceUpdated(reserve,totalSupply(),p);
    }

    /// @dev Builder-only capacity multiplier, read by the binary-owned authorization ledger.
    ///      The sync is automatic on protocol buys/sells and can also be called permissionlessly.
    function syncPriceMilestone() external {_syncMilestone();}
    function _syncMilestone() private {
        // A bootstrap/historical reference is not a live reserve/share price.
        // Neither quarantined cash nor raw USD surplus earns a capacity increase.
        if(totalSupply()==0)return;
        uint256 currentPrice=price();
        while(currentPrice>=milestonePrice&&priceMultiplier<1024){
            priceMultiplier*=2;
            if(milestonePrice>type(uint256).max/10){milestonePrice=type(uint256).max;break;}
            milestonePrice*=10;
            emit MultiplierUpdated(priceMultiplier,milestonePrice);
        }
    }
    function advancePriceMilestone() external {_syncMilestone();}

    /// @notice No protocol lock: full wallet balance is transferable/redeemable, subject to slippage and dust checks.
    function locked(address) public pure returns(uint256){return 0;}
    function unlocked(address who) public view returns(uint256){return balanceOf(who);}
    function lockCount(address) public pure returns(uint256){return 0;}
    function lockInfo(address) external pure returns(Lock[] memory page){page=new Lock[](0);}
    function lockPage(address,uint256,uint256 limit) external pure returns(Lock[] memory page){
        require(limit>0&&limit<=64,'page limit');
        page=new Lock[](0);
    }
    function lockVersion() external pure returns(uint256){return 3;}

    function _update(address from,address to,uint256 value) internal override {
        if(from!=address(0)&&to!=address(0)){
            require(!paused()&&!emergencyExit,'transfers paused');
            require(!_reentrancyGuardEntered(),'reentrant transfer');
            _backed();
            // Zero-value transfers remain ERC20 no-ops. Internal mint/burn operations
            // bypass this branch, preventing a second tax on buys or redemptions.
            if(value>0){
                uint256 previousR=reserve;
                uint256 previousS=totalSupply();
                uint256 burnAmount=_fee(value,TRANSFER_BURN_BPS);
                require(value>burnAmount,'transfer dust');
                uint256 balance=balanceOf(from);
                if(balance<value)revert ERC20InsufficientBalance(from,balance,value);
                // transferFrom has already spent the gross allowance; all changes
                // roll back together if net amount or price growth is insufficient.
                super._update(from,address(0),burnAmount);
                super._update(from,to,value-burnAmount);
                _requireGrowth(previousR,previousS);
                _syncMilestone();
                _recordPrice();
                return;
            }
        }
        super._update(from,to,value);
    }

    /// @notice All tracked cash includes redeemable backing and protected cash.
    /// @dev Direct USD donations remain unaccounted surplus, never silently assigned.
    function accounting() external view returns(uint256 actual,uint256 accounted){
        return(usd.balanceOf(address(this)),reserve+priceProtectionFund);
    }
    function rescue(address asset,address to,uint256 amount) external nonReentrant {
        require(msg.sender==governance&&asset!=address(usd)&&asset!=address(this),'protected');
        IERC20(asset).safeTransfer(to,amount);
    }
}

FTIRetirementReviewToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {ERC20} from '@openzeppelin/contracts/token/ERC20/ERC20.sol';
import {IERC20} from '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import {IERC20Metadata} from '@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol';
import {SafeERC20} from '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import {ReentrancyGuard} from '@openzeppelin/contracts/utils/ReentrancyGuard.sol';
import {Pausable} from '@openzeppelin/contracts/utils/Pausable.sol';
import {Math} from '@openzeppelin/contracts/utils/math/Math.sol';

interface IRetirementMembership {
    function unitsOf(address) external view returns (uint256);
    function tokenBuyLimit(address) external view returns (uint256);
    function remainingTokenBuyAllowance(address) external view returns (uint256);
    function tokenBuySpent(address) external view returns (uint256);
    function authorizeTokenBuy(address,uint256) external;
    function development() external view returns(address);
    function token() external view returns(address);
    function usd() external view returns(address);
    function governance() external view returns(address);
    function guardian() external view returns(address);
    function totalAuto() external view returns(uint256);
    function phase() external view returns(uint8);
    function epochUnits() external view returns(uint256);
    function monthPhase() external view returns(uint8);
    function jobCursor() external view returns(uint256);
    function jobCount() external view returns(uint256);
    function paused() external view returns(bool);
}
interface IRetirementTimelock {
    function getMinDelay() external view returns(uint256);
    function PROPOSER_ROLE() external view returns(bytes32);
    function hasRole(bytes32,address) external view returns(bool);
}
interface IRetirementCouncil {
    function OWNER_COUNT() external view returns(uint8);
    function THRESHOLD() external view returns(uint8);
}

/// @notice SEPARATE LOCAL lifecycle review. Not a deployed upgrade or a final release.
/// @dev The prior fee/gate candidate stays unchanged in FTIReserveToken.sol.
///      Ordinary terminal sales pay net of the current-trade fee; that terminal
///      fee becomes an owed development claim, never ownerless live reserve.
///      Governance may permanently retire only after zero supply/backing/claims
///      and a quiescent bound binary, through the existing 5/7 and 72h machinery.
///      All retirement USD goes to the fixed development-fund review parameter.
contract FTIRetirementReviewToken is ERC20, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    uint256 public constant WAD = 1e18;
    uint256 public constant INITIAL_PRICE = 1e17;
    uint256 public constant FEE_BPS = 300;
    uint256 public constant TRANSFER_BURN_BPS = 300;
    uint256 public constant RETAINED_BPS = 300;
    // Threshold correction approved for local review; 7% coefficient remains provisional.
    uint256 public constant LARGE_TRADE_MIN_USD = 500e18;
    uint256 public constant LARGE_TRADE_THRESHOLD_BPS = 500;
    uint256 public constant MAX_SIZE_FEE_BPS = 700;
    uint256 public constant MAX_SELL_FEE_BPS = FEE_BPS+MAX_SIZE_FEE_BPS;
    uint256 public constant MAX_BUY_FEE_BPS = FEE_BPS+MAX_SIZE_FEE_BPS;
    // Explicitly disabled pressure compatibility getters. No temporal fee exists.
    bool public constant SELL_PRESSURE_ACTIVE = false;
    uint256 public constant MAX_PRESSURE_FEE_BPS = 0;
    uint256 public constant PRESSURE_HALF_LIFE = 0;
    uint256 public constant PRESSURE_DECAY_PER_SECOND = 0;
    uint256 public constant MAX_PRESSURE_DECAY_SECONDS = 0;
    // Deprecated compatibility getters: zero means DISABLED, never a 0% sale cap.
    bool public constant SELL_CAPS_ACTIVE = false;
    uint256 public constant MAX_SINGLE_SELL_BPS = 0;
    uint256 public constant MAX_HOURLY_GROSS_SELL_BPS = 0;
    uint256 public constant MAX_RESERVE = 1e30;
    uint256 public constant MAX_SUPPLY = 1e36;
    uint256 public constant MIN_MINT = 1e6;
    uint256 public constant CAP_REFERENCE_SUPPLY = 1000000e18;
    bytes32 public constant pricingModel = 'RETIREMENT_REVIEW_SIZE_FEE';

    IERC20 public immutable usd;
    address public immutable governance;
    address public immutable guardian;
    address public immutable deployer;
    IRetirementMembership public binary;
    address public immutable developmentFund; // Actual public address still requires deployment review.
    uint256 public developmentFeeClaim; // Reserved liability, outside redeemable R and protected support.
    bool public permanentlyRetired;
    mapping(bytes4=>uint256) public councilApprovalAt;
    uint256 public constant RETIREMENT_DELAY = 72 hours;

    uint256 public reserve; // Redeemable backing of circulating FTI only; terminal development claims excluded.
    uint256 public priceProtectionFund; // No active-price release; retirement-only disposition is explicit below.
    uint256 public constant launchPrice = INITIAL_PRICE; // Fixed milestone anchor, not the first buy quote.
    uint256 public milestonePrice = INITIAL_PRICE*10;
    uint256 public ath; // status/compatibility metric, not a guaranteed liquidation price
    uint256 public walletClock; // registration metric only; never used for token locks
    uint256 public priceMultiplier = 1;
    uint256 public cumulativeBuy;
    uint256 public cumulativeSell;

    struct Lock {uint256 amount;uint64 clock;uint64 deadline;}

    // Deprecated compatibility counters; no windows or capacity checks are active.
    uint256 public sellWindowStart;
    uint256 public sellWindowStartReserve;
    uint256 public sellWindowGross;
    bool public emergencyExit;
    bool public lifecycleClosed; // Restart remains review-gated pending explicit approval.
    uint256 public referencePrice = INITIAL_PRICE;
    uint256 public constant pressureWad = 0; // Deprecated; pressure is disabled.
    uint256 public constant lastPartialSellAt = 0; // Deprecated; no fee timer exists.


    event Bound(address indexed binary);
    event TerminalDevelopmentFeeCredited(uint256 amount,uint256 totalClaim);
    event DevelopmentFeeClaimPaid(address indexed destination,uint256 amount);
    event RetirementActionApproved(bytes4 indexed action,uint256 approvedAt,uint256 executableAfter);
    event RetirementActionRevoked(bytes4 indexed action);
    event PermanentlyRetired(address indexed destination,uint256 protectedSupport,uint256 untrackedSurplusRemaining);
    event RetiredDonationRecovered(address indexed destination,uint256 amount);
    event Bought(address indexed wallet,uint256 usdIn,uint256 userTokens,bool automatic);
    event Sold(address indexed wallet,uint256 tokens,uint256 usdOut,uint256 baseFeeBps,uint256 impactBps);
    event ReserveInjected(uint256 amount);
    event ReserveQuarantined(uint256 amount,uint256 totalUnallocated);
    event MultiplierUpdated(uint256 multiplier,uint256 nextMilestone);
    event ReservePriceUpdated(uint256 reserve,uint256 shares,uint256 price);
    event EmergencyExitActivated(address indexed caller);
    event EmergencyExitDeactivated();
    event LifecycleClosed(uint256 residualReserve,uint256 referencePrice,bool emergency);
    event SellWindowReset(uint256 indexed start,uint256 reserveSnapshot);
    // Deprecated compatibility event; never emitted by this proposal.
    event SellPressureUpdated(uint256 pressureWad,uint256 timestamp);

    modifier onlyBinary(){require(msg.sender==address(binary),'binary only');_;}

    constructor(address stable,address gov,address emergency,address development)
        ERC20('FTI Protocol','FTI')
    {
        require(stable.code.length>0&&gov.code.length>0&&emergency.code.length>0,'addresses');
        require(development!=address(0)&&development!=address(this)&&development!=stable,'development destination');
        require(IRetirementTimelock(gov).getMinDelay()==72 hours,'72h governance');
        require(IRetirementCouncil(emergency).OWNER_COUNT()==7&&IRetirementCouncil(emergency).THRESHOLD()==5,'5 of 7 council');
        require(IRetirementTimelock(gov).hasRole(IRetirementTimelock(gov).PROPOSER_ROLE(),emergency),'council proposer');
        developmentFund=development;
        require(IERC20Metadata(stable).decimals()==18,'requires 18 decimal USD');
        usd=IERC20(stable);
        governance=gov;
        guardian=emergency;
        deployer=msg.sender;
    }

    function bind(address c1) external {
        require(msg.sender==deployer&&address(binary)==address(0)&&c1.code.length>0,'bind');
        IRetirementMembership candidate=IRetirementMembership(c1);
        require(c1!=developmentFund&&candidate.development()==developmentFund,'development mismatch');
        require(candidate.token()==address(this)&&candidate.usd()==address(usd)&&
            candidate.governance()==governance&&candidate.guardian()==guardian,'binary binding mismatch');
        binary=candidate;
        emit Bound(c1);
    }

    /// @dev Pause blocks buys and wallet-to-wallet transfers. Sells remain open.
    function pause() external {require(msg.sender==guardian||msg.sender==governance,'role');_pause();}
    function unpause() external {require(msg.sender==governance,'governance');require(!permanentlyRetired,'permanently retired');_unpause();}

    /// @notice 7-wallet council (guardian) may activate after its on-chain threshold vote.
    ///         This does not transfer reserve to administrators; it makes the protocol redemption-only.
    function activateEmergencyExit() external {
        require(msg.sender==guardian||msg.sender==governance,'role');
        require(!permanentlyRetired,'permanently retired');
        emergencyExit=true;
        if(!paused())_pause();
        emit EmergencyExitActivated(msg.sender);
    }
    function deactivateEmergencyExit() external {
        require(msg.sender==governance,'governance');
        require(!permanentlyRetired,'permanently retired');
        emergencyExit=false;
        if(paused())_unpause();
        emit EmergencyExitDeactivated();
    }

    function circulatingSupply() public view returns(uint256){return totalSupply();}
    /// @notice At zero supply this is a historical/bootstrap reference, not redeemable value.
    function price() public view returns(uint256){
        return totalSupply()==0?referencePrice:Math.mulDiv(reserve,WAD,totalSupply());
    }
    function buybackFund() external pure returns(uint256){return 0;}
    function floorFund() external pure returns(uint256){return 0;}
    function anchorSupply() external pure returns(uint256){return 0;}
    /// @notice Base fee only. Use buyFeeQuote(amount) for the actual fee amount.
    function buyFeeBps() external pure returns(uint256){return FEE_BPS;}
    /// @notice Deprecated name for protected price-protection-fund cash.
    function unallocatedReserve() external view returns(uint256){return priceProtectionFund;}

    /// @notice Cumulative manual-buy authorization is owned by the binary contract.
    ///         Each paid unit grants its rank-based capacity; selling never restores quota.
    function buyLimit(address who) public view returns(uint256){return binary.tokenBuyLimit(who);}
    function remainingAllowance(address who) public view returns(uint256){return binary.remainingTokenBuyAllowance(who);}
    function lifetimeManualBuys(address who) external view returns(uint256){return binary.tokenBuySpent(who);}

    function _fee(uint256 amount,uint256 bps) private pure returns(uint256){
        return Math.mulDiv(amount,bps,10000,Math.Rounding.Ceil);
    }
    /// @dev T = max(500 USD, R/20), keeping fractional USD atoms exact.
    ///      With thresholdTimes20=max(20*500e18,R), X=max(20V-thresholdTimes20,0).
    ///      B=X/20 and F=ceil((300*400*V^2+700*X^2)/(10000*400*V)).
    ///      One combined rational amount receives ONE ceil. V,R<=1e30 bounds
    ///      the numerator by 4e65 (<2^256) and denominator by 4e36.
    ///      R=0/S=0 retains the existing base-only bootstrap review exception.
    function _sizeExcessTimes20(uint256 value) private view returns(uint256){
        uint256 thresholdTimes20=Math.max(LARGE_TRADE_MIN_USD*20,reserve);
        return value*20>thresholdTimes20?value*20-thresholdTimes20:0;
    }
    function _tradeFee(uint256 value) private view returns(uint256){
        require(value<=MAX_RESERVE&&reserve<=MAX_RESERVE,'fee range');
        if(value==0)return 0;
        if(totalSupply()==0||reserve==0)return _fee(value,FEE_BPS);
        uint256 excessTimes20=_sizeExcessTimes20(value);
        if(excessTimes20==0)return _fee(value,FEE_BPS);
        uint256 numerator=FEE_BPS*400*value*value+MAX_SIZE_FEE_BPS*excessTimes20*excessTimes20;
        uint256 denominator=10000*400*value;
        return Math.ceilDiv(numerator,denominator);
    }

    /// @notice Amount-specific total fee in USD atoms and net minting value.
    /// @dev All amount is retained in reserve; only netAssets mints FTI.
    ///      Zero netAssets is a dust quote and cannot execute as a buy.
    function buyFeeQuote(uint256 amount) public view returns(uint256 feeAmount,uint256 netAssets){
        require(amount>0&&amount<=MAX_RESERVE,'amount');
        feeAmount=_tradeFee(amount);
        netAssets=amount-feeAmount;
    }

    /// @notice Only net-of-fee user value mints tokens. Restart after final redemption is disabled.
    function quoteBuy(uint256 amount) public view returns(uint256){
        require(!permanentlyRetired,'permanently retired');
        require(!lifecycleClosed,'restart policy pending');
        (,uint256 userAssets)=buyFeeQuote(amount);
        require(userAssets>0,'dust');
        uint256 prePrice=price();
        require(prePrice>0,'reserve');
        return Math.mulDiv(userAssets,WAD,prePrice);
    }

    /// @notice Deprecated compatibility views: temporal/global pressure is disabled.
    function currentSellPressure() public pure returns(uint256){return 0;}
    function previewSellPressure(uint256 tokens) public view returns(uint256){
        require(tokens<=totalSupply(),'supply');
        return 0;
    }

    /// @notice Truncated indicative average surcharge in bps, NOT a fee calculator.
    /// @dev Use sellFeeQuote for the exact, once-rounded USD fee. A sub-bps size
    ///      surcharge can exist even when this compatibility display returns zero.
    function sellImpactBps(uint256 tokens) public view returns(uint256){
        uint256 supply=totalSupply();
        require(tokens<=supply,'supply');
        if(tokens==0||emergencyExit||reserve==0)return 0;
        uint256 gross=Math.mulDiv(tokens,reserve,supply);
        require(gross<=MAX_RESERVE&&reserve<=MAX_RESERVE,'fee range');
        uint256 excessTimes20=_sizeExcessTimes20(gross);
        if(excessTimes20==0)return 0;
        return Math.mulDiv(MAX_SIZE_FEE_BPS,excessTimes20*excessTimes20,400*gross*gross);
    }

    /// @notice Exact USD fee and payout. Only emergency exits remain fee-free; normal terminal fees are reserved development claims.
    function sellFeeQuote(uint256 tokens) public view returns(uint256 feeAmount,uint256 payout,uint256 gross){
        uint256 supply=totalSupply();
        require(tokens<=supply,'supply');
        if(tokens==0||supply==0)return(0,0,0);
        gross=Math.mulDiv(tokens,reserve,supply);
        if(!emergencyExit)feeAmount=_tradeFee(gross);
        require(gross>feeAmount,'dust');
        payout=gross-feeAmount;
    }

    /// @notice Legacy quote shape; feeBps is truncated indicative average only.
    /// @dev Never reconstruct the fee from feeBps. sellFeeQuote exposes exact USD.
    function quoteSell(uint256 tokens) public view returns(uint256 payout,uint256 feeBps,uint256 gross){
        (,payout,gross)=sellFeeQuote(tokens);
        feeBps=emergencyExit?0:FEE_BPS+sellImpactBps(tokens);
    }

    /// @notice Binary funding never creates FTI. Only funding received while supply
    ///         is positive becomes redeemable backing. Zero-supply cash remains
    ///         in the price-protection fund, including after closure and later buys.
    function inject(uint256 amount,bool newWallet) external onlyBinary nonReentrant {
        require(!permanentlyRetired,'permanently retired');
        require(amount>0&&amount<=MAX_RESERVE&&reserve+priceProtectionFund+developmentFeeClaim+amount<=MAX_RESERVE,'reserve range');
        _receive(msg.sender,amount);
        if(totalSupply()==0){
            priceProtectionFund+=amount;
            emit ReserveQuarantined(amount,priceProtectionFund);
        }else reserve+=amount;
        if(newWallet)walletClock++;
        _backed();
        _syncMilestone();
        _recordPrice();
        emit ReserveInjected(amount);
    }

    function buy(uint256 amount,uint256 minTokens,uint256 deadline)
        external nonReentrant whenNotPaused returns(uint256)
    {
        require(!emergencyExit,'redemption only');
        return _buy(msg.sender,msg.sender,amount,minTokens,deadline,false);
    }
    function autoBuy(address who,uint256 amount,uint256 minTokens,uint256 deadline)
        external onlyBinary nonReentrant whenNotPaused returns(uint256)
    {
        require(!emergencyExit,'redemption only');
        return _buy(msg.sender,who,amount,minTokens,deadline,true);
    }

    function _buy(address payer,address who,uint256 amount,uint256 minTokens,uint256 deadline,bool automatic)
        private returns(uint256 minted)
    {
        require(!permanentlyRetired,'permanently retired');
        require(!lifecycleClosed,'restart policy pending');
        require(block.timestamp<=deadline&&amount>0&&binary.unitsOf(who)>0,'buy input');

        uint256 previousR=reserve;
        uint256 previousS=totalSupply();
        minted=quoteBuy(amount);
        require(minted>=MIN_MINT&&minted>=minTokens,'slippage/dust');
        require(reserve+priceProtectionFund+developmentFeeClaim+amount<=MAX_RESERVE&&previousS+minted<=MAX_SUPPLY,'range');

        // The binary consumes manual authorization before collateral moves. Any later
        // failure reverts both the quota and token state in the same transaction.
        if(!automatic)binary.authorizeTokenBuy(who,amount);
        _receive(payer,amount);
        reserve+=amount;

        _mint(who,minted);
        cumulativeBuy+=amount;

        if(previousS>0)_requireGrowth(previousR,previousS);
        else require(price()>referencePrice,'price step too small');
        _syncMilestone();
        _recordPrice();
        emit Bought(who,amount,minted,automatic);
    }

    function sell(uint256 tokens,uint256 minUSD,uint256 deadline)
        external nonReentrant returns(uint256 payout)
    {
        require(block.timestamp<=deadline&&tokens>0&&tokens<=balanceOf(msg.sender),'sell input');
        uint256 supply=circulatingSupply();
        bool finalRedemption=tokens==supply;

        uint256 gross;uint256 totalFeeBps;
        (payout,totalFeeBps,gross)=quoteSell(tokens);
        require(payout>0&&payout>=minUSD&&payout<=reserve,'slippage/dust');

        uint256 previousR=reserve;
        uint256 previousS=totalSupply();
        uint256 previousPrice=price();

        reserve-=payout;
        cumulativeSell+=gross;
        _burn(msg.sender,tokens);

        if(finalRedemption){
            // Normal terminal fee is an explicit owed development claim. There
            // is no live R/S after burning all shares and no silent fee residue.
            uint256 terminalFee=reserve; // previousR - payout; emergency fee is zero.
            reserve=0;
            if(terminalFee>0){
                developmentFeeClaim+=terminalFee;
                emit TerminalDevelopmentFeeCredited(terminalFee,developmentFeeClaim);
            }
            referencePrice=previousPrice;
            lifecycleClosed=true;
            _backed();
            emit LifecycleClosed(0,referencePrice,emergencyExit);
        }else if(emergencyExit)_backed();
        else _requireGrowth(previousR,previousS);
        _syncMilestone();
        _recordPrice();

        uint256 beforePool=usd.balanceOf(address(this));
        uint256 beforeUser=usd.balanceOf(msg.sender);
        usd.safeTransfer(msg.sender,payout);
        require(beforePool-usd.balanceOf(address(this))==payout&&
            usd.balanceOf(msg.sender)-beforeUser==payout,'unsupported USD');
        _backed();
        emit Sold(msg.sender,tokens,payout,totalFeeBps==0?0:FEE_BPS,totalFeeBps>FEE_BPS?totalFeeBps-FEE_BPS:0);
    }

    function _receive(address payer,uint256 amount) private {
        _backed();
        uint256 beforeBalance=usd.balanceOf(address(this));
        uint256 beforePayer=usd.balanceOf(payer);
        usd.safeTransferFrom(payer,address(this),amount);
        require(usd.balanceOf(address(this))-beforeBalance==amount&&
            beforePayer-usd.balanceOf(payer)==amount,'unsupported USD');
    }

    function _backed() private view {require(usd.balanceOf(address(this))>=reserve+priceProtectionFund+developmentFeeClaim,'reserve deficit');}
    function _requireGrowth(uint256 oldR,uint256 oldS) private view {
        require(oldS>0&&totalSupply()>0,'supply');
        require(reserve*oldS>oldR*totalSupply(),'price must increase');
        // Strict exact growth alone may be invisible after WAD rounding. Reject
        // a trade too small to advance the actual displayed reserve/share price.
        require(price()>Math.mulDiv(oldR,WAD,oldS),'price step too small');
        _backed();
    }
    function _recordPrice() private {
        uint256 p=price();
        if(p>ath)ath=p;
        emit ReservePriceUpdated(reserve,totalSupply(),p);
    }

    /// @dev Builder-only capacity multiplier, read by the binary-owned authorization ledger.
    ///      The sync is automatic on protocol buys/sells and can also be called permissionlessly.
    function syncPriceMilestone() external {_syncMilestone();}
    function _syncMilestone() private {
        // A bootstrap/historical reference is not a live reserve/share price.
        // Neither quarantined cash nor raw USD surplus earns a capacity increase.
        if(totalSupply()==0)return;
        uint256 currentPrice=price();
        while(currentPrice>=milestonePrice&&priceMultiplier<1024){
            priceMultiplier*=2;
            if(milestonePrice>type(uint256).max/10){milestonePrice=type(uint256).max;break;}
            milestonePrice*=10;
            emit MultiplierUpdated(priceMultiplier,milestonePrice);
        }
    }
    function advancePriceMilestone() external {_syncMilestone();}

    /// @notice No protocol lock: full wallet balance is transferable/redeemable, subject to slippage and dust checks.
    function locked(address) public pure returns(uint256){return 0;}
    function unlocked(address who) public view returns(uint256){return balanceOf(who);}
    function lockCount(address) public pure returns(uint256){return 0;}
    function lockInfo(address) external pure returns(Lock[] memory page){page=new Lock[](0);}
    function lockPage(address,uint256,uint256 limit) external pure returns(Lock[] memory page){
        require(limit>0&&limit<=64,'page limit');
        page=new Lock[](0);
    }
    function lockVersion() external pure returns(uint256){return 3;}

    function _update(address from,address to,uint256 value) internal override {
        if(from!=address(0)&&to!=address(0)){
            require(!paused()&&!emergencyExit,'transfers paused');
            require(!_reentrancyGuardEntered(),'reentrant transfer');
            _backed();
            // Zero-value transfers remain ERC20 no-ops. Internal mint/burn operations
            // bypass this branch, preventing a second tax on buys or redemptions.
            if(value>0){
                uint256 previousR=reserve;
                uint256 previousS=totalSupply();
                uint256 burnAmount=_fee(value,TRANSFER_BURN_BPS);
                require(value>burnAmount,'transfer dust');
                uint256 balance=balanceOf(from);
                if(balance<value)revert ERC20InsufficientBalance(from,balance,value);
                // transferFrom has already spent the gross allowance; all changes
                // roll back together if net amount or price growth is insufficient.
                super._update(from,address(0),burnAmount);
                super._update(from,to,value-burnAmount);
                _requireGrowth(previousR,previousS);
                _syncMilestone();
                _recordPrice();
                return;
            }
        }
        super._update(from,to,value);
    }

    /// @notice All tracked cash includes live backing, protected support and owed development fees.
    /// @dev Direct USD donations remain unaccounted surplus, never silently assigned.
    function accounting() external view returns(uint256 actual,uint256 accounted){
        return(usd.balanceOf(address(this)),reserve+priceProtectionFund+developmentFeeClaim);
    }
    /// @notice Anyone may trigger payment of the already-owed terminal fee to
    ///         the fixed development fund; no caller-supplied recipient exists.
    function claimDevelopmentFees() external nonReentrant {
        _backed();
        uint256 amount=developmentFeeClaim;
        require(amount>0,'no development claim');
        developmentFeeClaim=0;
        _payDevelopment(amount);
        _backed();
        emit DevelopmentFeeClaimPaid(developmentFund,amount);
    }

    /// @dev Constant-time checks only. Binary reward cash stays in the binary;
    ///      its totalAuto is the aggregate earmarked for future token buys.
    ///      Pausing, clearing jobs and closing this hour prevent new auto claims
    ///      from being created by a half-finished settlement after retirement.
    function _requireRetirementReady() private view {
        require(totalSupply()==0&&reserve==0,'active token backing');
        require(developmentFeeClaim==0,'pending token claims');
        require(address(binary)!=address(0),'binary not bound');
        require(binary.totalAuto()==0,'pending auto claims');
        require(binary.paused()&&binary.phase()==0&&binary.monthPhase()==0&&binary.epochUnits()==0&&
            binary.jobCursor()==binary.jobCount(),'binary not quiescent');
        _backed();
    }

    /// @notice A separate explicit Council vote is required for each terminal
    ///         action, even if timelock proposer roles are expanded in future.
    ///         This approval and timelock scheduling can occur concurrently;
    ///         their 72h waits do not have to be serial.
    function approveRetirementAction(bytes4 action) external nonReentrant {
        require(msg.sender==guardian,'council only');
        require(action==this.retirePermanently.selector||action==this.recoverRetiredDonations.selector,'retirement action');
        if(action==this.retirePermanently.selector)require(!permanentlyRetired,'permanently retired');
        else require(permanentlyRetired,'not retired');
        councilApprovalAt[action]=block.timestamp;
        emit RetirementActionApproved(action,block.timestamp,block.timestamp+RETIREMENT_DELAY);
    }

    /// @notice The Council can revoke a still-pending token authorization;
    ///         cancelling a timelock operation alone does not erase this approval.
    function revokeRetirementAction(bytes4 action) external nonReentrant {
        require(msg.sender==guardian,'council only');
        require(action==this.retirePermanently.selector||action==this.recoverRetiredDonations.selector,'retirement action');
        councilApprovalAt[action]=0;
        emit RetirementActionRevoked(action);
    }

    function _consumeCouncilApproval(bytes4 action) private {
        uint256 approvedAt=councilApprovalAt[action];
        require(approvedAt>0&&block.timestamp>=approvedAt+RETIREMENT_DELAY,'council approval/delay');
        councilApprovalAt[action]=0;
    }

    /// @notice Council-approved permanent termination, executed by the 72h
    ///         timelock. No live backing or unsettled token claim may be swept.
    /// @dev Protected support goes to the fixed development fund. Unaccounted
    ///      USD is disclosed separately and stays until a distinct Council-
    ///      approved delayed recovery action. Other binary cash is untouched.
    function retirePermanently() external nonReentrant {
        require(msg.sender==governance,'governance');
        require(!permanentlyRetired,'permanently retired');
        _requireRetirementReady();
        _consumeCouncilApproval(msg.sig);
        uint256 actual=usd.balanceOf(address(this));
        uint256 support=priceProtectionFund;
        uint256 surplus=actual-support;
        permanentlyRetired=true;
        lifecycleClosed=true;
        if(!paused())_pause();
        priceProtectionFund=0;
        if(support>0)_payDevelopment(support);
        _backed();
        emit PermanentlyRetired(developmentFund,support,surplus);
    }

    /// @notice A retired ERC20 address can still receive unsolicited USD.
    ///         The same delayed governance may recover untracked USD left at
    ///         retirement or received later, always
    ///         to the same fixed fund, without reopening any lifecycle.
    function recoverRetiredDonations() external nonReentrant {
        require(msg.sender==governance,'governance');
        require(permanentlyRetired,'not retired');
        _requireRetirementReady();
        require(priceProtectionFund==0,'protected support');
        _consumeCouncilApproval(msg.sig);
        uint256 amount=usd.balanceOf(address(this));
        require(amount>0,'no surplus');
        _payDevelopment(amount);
        _backed();
        emit RetiredDonationRecovered(developmentFund,amount);
    }

    function _payDevelopment(uint256 amount) private {
        uint256 beforePool=usd.balanceOf(address(this));
        uint256 beforeFund=usd.balanceOf(developmentFund);
        usd.safeTransfer(developmentFund,amount);
        require(beforePool-usd.balanceOf(address(this))==amount&&
            usd.balanceOf(developmentFund)-beforeFund==amount,'unsupported USD');
    }

    function rescue(address asset,address to,uint256 amount) external nonReentrant {
        require(msg.sender==governance&&asset!=address(usd)&&asset!=address(this),'protected');
        IERC20(asset).safeTransfer(to,amount);
    }
}

FTIToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;
import {ERC20} from '@openzeppelin/contracts/token/ERC20/ERC20.sol';
import {IERC20} from '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import {SafeERC20} from '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import {ReentrancyGuard} from '@openzeppelin/contracts/utils/ReentrancyGuard.sol';
import {Pausable} from '@openzeppelin/contracts/utils/Pausable.sol';
interface IBinary {
    function unitsOf(address) external view returns(uint256);
    function rankOf(address) external view returns(uint8);
    function registered(address) external view returns(bool);
}
/// @notice Experimental bounded-integer implementation. NOT audited for mainnet.
contract FTIToken is ERC20, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;
    uint256 public constant WAD=1e18;
    uint256 public constant V=20000e18;
    uint256 public constant S0=1000000e18;
    uint256 public constant P0=1e17;
    uint256 public constant MAX_RESERVE=1e30;
    IERC20 public immutable usd;
    address public immutable governance;
    address public immutable guardian;
    address public immutable deployer;
    IBinary public binary;
    uint256 public reserve;
    uint256 public buybackFund;
    uint256 public floorFund;
    uint256 public ath=P0;
    uint256 public walletClock;
    uint256 public priceMultiplier=1;
    uint256 public milestonePrice=P0;
    uint256 public cumulativeBuy;
    uint256 public cumulativeSell;
    mapping(uint256=>uint256) public startBuy;
    mapping(uint256=>uint256) public startSell;
    mapping(address=>uint256) public lifetimeManualBuys;
    struct Lock {uint256 amount; uint64 clock; uint64 deadline;}
    mapping(address=>Lock[]) private locks;
    event Bound(address indexed binary);
    event Bought(address indexed wallet,uint256 usdIn,uint256 tokens,bool automatic);
    event Sold(address indexed wallet,uint256 tokens,uint256 usdOut,uint256 feeBps);
    event ReserveInjected(uint256 amount);
    event Supported(uint256 buyback,uint256 floor);
    event MultiplierUpdated(uint256 multiplier);
    modifier onlyBinary(){require(msg.sender==address(binary),'binary only');_;}
    constructor(address stable,address gov,address emergency) ERC20('FTI Protocol','FTI') {
        require(stable!=address(0)&&gov!=address(0)&&emergency!=address(0),'zero');
        usd=IERC20(stable); governance=gov; guardian=emergency; deployer=msg.sender;
    }
    function bind(address c1) external {require(msg.sender==deployer&&address(binary)==address(0)&&c1.code.length>0,'bind');binary=IBinary(c1);emit Bound(c1);}
    function pause() external {require(msg.sender==guardian||msg.sender==governance,'role');_pause();}
    function unpause() external {require(msg.sender==governance,'governance');_unpause();}
    function curveSupply() public view returns(uint256){return S0+totalSupply();}
    function price() public view returns(uint256){return (reserve+V)*5*WAD/curveSupply();}
    function _ceil(uint256 a,uint256 b) private pure returns(uint256){return a/b+(a%b==0?0:1);}
    function _pow5Up(uint256 ratio) private pure returns(uint256 r){r=WAD;for(uint256 i;i<5;i++)r=_ceil(r*ratio,WAD);}
    function _cost(uint256 s,uint256 m) private view returns(uint256){uint256 ratio=_ceil((s+m)*WAD,s);return _ceil((reserve+V)*(_pow5Up(ratio)-WAD),WAD);}
    function buyLimit(address who) public view returns(uint256){uint256[5] memory limits=[uint256(500),600,700,800,1000];return binary.unitsOf(who)*limits[binary.rankOf(who)]*WAD*priceMultiplier;}
    function remainingAllowance(address who) public view returns(uint256){uint256 lim=buyLimit(who);return lim>lifetimeManualBuys[who]?lim-lifetimeManualBuys[who]:0;}
    function buyFeeBps() public view returns(uint256){return price()*100<=ath*90?120:300;}
    function quoteBuy(uint256 amount) public view returns(uint256 minted){
        require(amount<=MAX_RESERVE,'amount limit');
        uint256 net=amount-amount*buyFeeBps()/10000;
        uint256 s=curveSupply(); uint256 lo; uint256 hi=s;
        while(_cost(s,hi)<=net){hi*=2;}
        // Bounds: reserve <= 1e30, supply <= S0+1e30. 128 bisections cover the entire allowed range.
        while(lo<hi){uint256 mid=lo+(hi-lo+1)/2;if(_cost(s,mid)<=net)lo=mid;else hi=mid-1;}
        return lo;
    }
    function inject(uint256 amount,bool newWallet) external onlyBinary nonReentrant {
        if(newWallet){walletClock++;startBuy[walletClock]=cumulativeBuy;startSell[walletClock]=cumulativeSell;}
        require(reserve+buybackFund+floorFund+amount<=MAX_RESERVE,'reserve range');
        uint256 beforeBal=usd.balanceOf(address(this));usd.safeTransferFrom(msg.sender,address(this),amount);
        require(usd.balanceOf(address(this))-beforeBal==amount,'unsupported USD');
        buybackFund+=amount*80/100;floorFund+=amount-amount*80/100;_defend();emit ReserveInjected(amount);
    }
    function buy(uint256 amount,uint256 minTokens,uint256 deadline) external nonReentrant whenNotPaused returns(uint256){return _buy(msg.sender,msg.sender,amount,minTokens,deadline,false);}
    function autoBuy(address who,uint256 amount,uint256 minTokens,uint256 deadline) external onlyBinary nonReentrant whenNotPaused returns(uint256){return _buy(msg.sender,who,amount,minTokens,deadline,true);}
    function _buy(address payer,address who,uint256 amount,uint256 minTokens,uint256 deadline,bool automatic) private returns(uint256 minted){
        require(block.timestamp<=deadline&&amount>0&&binary.unitsOf(who)>0,'buy input');
        if(!automatic)require(amount<=remainingAllowance(who),'allowance');
        minted=quoteBuy(amount);require(minted>0&&minted>=minTokens,'slippage/dust');
        require((balanceOf(who)+minted)*100<=curveSupply()+minted,'holding cap');
        uint256 fee=amount*buyFeeBps()/10000;
        require(reserve+buybackFund+floorFund+amount<=MAX_RESERVE&&curveSupply()+minted<=1e30,'range');
        uint256 beforeBal=usd.balanceOf(address(this));usd.safeTransferFrom(payer,address(this),amount);
        require(usd.balanceOf(address(this))-beforeBal==amount,'unsupported USD');
        reserve+=amount-fee;buybackFund+=fee;
        if(!automatic)lifetimeManualBuys[who]+=amount;
        _mint(who,minted);_prune(who);
        bool vest=!automatic&&lifetimeManualBuys[who]>=500e18;
        require(locks[who].length+(vest?4:1)<=64,'claim mature locks first');
        if(vest){uint256 part=minted/4;for(uint256 i;i<4;i++)locks[who].push(Lock(i==3?minted-3*part:part,uint64(walletClock+20000+8000*i),uint64(block.timestamp+90 days)));}
        else locks[who].push(Lock(minted,uint64(walletClock+5000),uint64(block.timestamp+30 days)));
        cumulativeBuy+=amount;_defend();emit Bought(who,amount,minted,automatic);
    }
    function lockInfo(address who) external view returns(Lock[] memory){return locks[who];}
    function locked(address who) public view returns(uint256 amount){for(uint256 i;i<locks[who].length;i++){Lock memory l=locks[who][i];if(walletClock<l.clock&&block.timestamp<l.deadline)amount+=l.amount;}}
    function unlocked(address who) public view returns(uint256){return balanceOf(who)-locked(who);}
    function _prune(address who) private {uint256 i;while(i<locks[who].length){Lock memory l=locks[who][i];if(walletClock>=l.clock||block.timestamp>=l.deadline){locks[who][i]=locks[who][locks[who].length-1];locks[who].pop();}else i++;}}
    function pruneLocks() external {_prune(msg.sender);}
    function sustainedActive() public view returns(bool){uint256 from=walletClock>=4999?walletClock-4999:0;uint256 s=cumulativeSell-startSell[from];uint256 b=cumulativeBuy-startBuy[from];return s>=1000e18&&s*10>=b*13;}
    function quoteSell(uint256 tokens) public view returns(uint256 payout,uint256 feeBps,uint256 gross){
        require(tokens<=totalSupply(),'supply');uint256 s=curveSupply();uint256 remaining=_ceil((s-tokens)*WAD,s);
        gross=(reserve+V)*(WAD-_pow5Up(remaining))/WAD;
        uint256 rho=gross*10000/(reserve+V);feeBps=300;
        if(rho>100){uint256 slope=rho>=1000?900:rho-100;feeBps+=5700*slope/900;}
        if(sustainedActive()&&feeBps<1500)feeBps=1500;
        payout=gross*(10000-feeBps)/10000;
    }
    function sell(uint256 tokens,uint256 minUSD,uint256 deadline) external nonReentrant whenNotPaused returns(uint256 payout){
        require(block.timestamp<=deadline&&tokens>0&&tokens<=unlocked(msg.sender),'sell input/lock');
        (uint256 out,uint256 fee,uint256 gross)=quoteSell(tokens);payout=out;require(out>=minUSD&&out>0,'slippage/dust');
        uint256 excess=gross*(fee-300)/10000;require(out+excess<=reserve,'reserve');
        reserve-=out+excess;buybackFund+=excess;cumulativeSell+=gross;_burn(msg.sender,tokens);
        _defend();usd.safeTransfer(msg.sender,out);emit Sold(msg.sender,tokens,out,fee);
    }
    function _update(address from,address to,uint256 value) internal override {
        if(from!=address(0)&&to!=address(0)){
            require(!paused()&&from!=to&&binary.unitsOf(to)>0,'transfer');require(value<=unlocked(from),'locked');
            uint256 burn=value*300/10000;uint256 received=value-burn;
            require((balanceOf(to)+received)*100<=curveSupply()-burn,'holding cap');
            super._update(from,address(0),burn);super._update(from,to,received);_defend();
        }else super._update(from,to,value);
    }
    function _defend() private {
        uint256 p=price();if(p>ath){ath=p;return;}uint256 bb;uint256 fl;
        if(p*100<=ath*99){uint256 target=ath*curveSupply()/(5*WAD);if(target>reserve+V){bb=target-reserve-V;if(bb>buybackFund)bb=buybackFund;buybackFund-=bb;reserve+=bb;}}
        if(price()*100<ath*92){uint256 target=ath*92*curveSupply()/(500*WAD);if(target>reserve+V){fl=target-reserve-V;if(fl>floorFund)fl=floorFund;floorFund-=fl;reserve+=fl;}}
        if(bb+fl>0)emit Supported(bb,fl);
    }
    function advancePriceMilestone() external {require(msg.sender==governance,'governance');require(price()>=milestonePrice*10&&priceMultiplier<1024,'milestone');milestonePrice*=10;priceMultiplier*=2;emit MultiplierUpdated(priceMultiplier);}
    function accounting() external view returns(uint256 actual,uint256 accounted){return(usd.balanceOf(address(this)),reserve+buybackFund+floorFund);}
    function rescue(address asset,address to,uint256 amount) external {require(msg.sender==governance&&asset!=address(usd)&&asset!=address(this),'protected');IERC20(asset).safeTransfer(to,amount);}
}

FundedBinaryPlan.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;
import {IERC20} from '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import {IERC20Metadata} from '@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol';
import {SafeERC20} from '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import {ReentrancyGuard} from '@openzeppelin/contracts/utils/ReentrancyGuard.sol';
import {Pausable} from '@openzeppelin/contracts/utils/Pausable.sol';
import {Math} from '@openzeppelin/contracts/utils/math/Math.sol';
import {IFTI, Calendar} from './BinaryPlan.sol';
/// @notice Candidate with source-attributed funding; global carried funds cannot fund unrelated rewards.
contract FundedBinaryPlan is ReentrancyGuard,Pausable {
    using SafeERC20 for IERC20;
    uint256 public constant UNIT=100e18;
    uint256 public constant MAX_BATCH=100;
    uint256 public constant MAX_DEPTH=64;
    uint256 public constant MAX_POINT_VALUE=20e18;
    bytes32 public constant rewardModel='ATTRIBUTED_CREDIT_V1';
    IERC20 public immutable usd;
    IFTI public immutable token;
    address public immutable governance;
    address public immutable guardian;
    address public immutable development;
    struct Member {address parent;address left;address right;uint256 units;uint256 carryL;uint256 carryR;uint256 lifetimeL;uint256 lifetimeR;uint8 rank;bool exists;bool autoEnabled;uint256 maxAutoPrice;}
    mapping(address=>Member) public members;
    /// @notice Gross manual FTI purchases authorized by this binary plan; sales never restore quota.
    mapping(address=>uint256) public tokenBuySpent;
    address[] public memberList;
    mapping(address=>uint64[4]) public rankReachedAt;
    mapping(address=>uint256) public depth;
    mapping(address=>uint256) public activatedAtSerial;
    uint256 public fundingSerial;
    mapping(address=>uint256) public creditL;
    mapping(address=>uint256) public creditR;
    uint256 public queuedPointCredit;
    uint256 public assignedPointCredit;
    uint256 public retainedPointReserve;
    uint256 public queuedBuilderCredit;
    uint256 public assignedBuilderCredit;
    uint256 public retainedBuilderReserve;
    mapping(uint256=>address) public dirtyMembers;
    mapping(address=>bool) private dirty;
    uint256 public dirtyCount;
    uint256 private matchedFunding;
    struct Job {address child;address ancestor;uint256 units;uint256 pointShare;uint256[4] builderShares;uint256 month;uint256 serial;}
    Job[] public jobs;uint256 public jobCursor;
    uint256 public epoch=1;uint256 public epochEnd;uint256 public lastClosedAt;
    uint256 public epochUnits;uint256 public unitsSinceSettlement;uint256 public pointPool;
    uint8 public protectionLevel;uint8 public frozenLevel;
    uint8 public phase; // 0 deposits, 1 matching, 2 allocation
    uint256 public cursor;uint256 public frozenMembers;uint256 public totalPaidPoints;uint256 public pointValue;uint256 public frozenPool;uint256 public allocated;
    mapping(uint256=>mapping(address=>uint256)) public paidPoints;
    mapping(uint256=>mapping(address=>bool)) public autoSnapshot;
    mapping(uint256=>mapping(address=>bool)) public settled;
    mapping(address=>uint256) public pendingReward;
    mapping(address=>uint256) public pendingAuto;
    uint256 public totalPending;uint256 public totalAuto;
    uint256 public builderAccounted;
    mapping(uint256=>uint256[4]) public monthFunding;
    uint256[4] public builderCarry;
    mapping(address=>bool[4]) public builderClaimed;
    uint256 public nextBuilderMonth;uint8 public monthPhase;uint256 public monthCursor;uint256 public monthMembers;
    uint256[4] public monthBalances;uint256[4] public monthEligible;uint256[4] public monthPay;
    mapping(uint256=>mapping(address=>uint256[4])) public builderCredit;
    mapping(uint256=>address[]) private builderAccounts;
    mapping(uint256=>mapping(address=>bool)) private builderSeen;
    uint256[4] public monthPaid;
    address[] public autoAccounts;
    mapping(address=>uint256) private autoIndex;
    event Registered(address indexed wallet,address indexed sponsor,uint256 units);
    event UnitsAdded(address indexed wallet,uint256 units);
    event EpochClosed(uint256 indexed epoch,uint256 pool,uint256 points,uint256 pointValue,uint8 nextProtection);
    event RewardAllocated(uint256 indexed epoch,address indexed wallet,uint256 cash,uint256 automatic);
    event Claimed(address indexed wallet,uint256 amount);
    event BuilderMonthClosed(uint256 indexed month);
    event AutoExecuted(address indexed wallet,uint256 usdIn,uint256 tokens);
    event TokenBuyAuthorized(address indexed wallet,uint256 usdIn,uint256 cumulativeSpent);
    constructor(address stable,address fti,address gov,address emergency,address dev,address[31] memory genesis){
        require(IERC20Metadata(stable).decimals()==18,'requires 18 decimal USD');
        require(fti.code.length>0&&gov!=address(0)&&emergency!=address(0)&&dev!=address(0),'addresses');
        usd=IERC20(stable);token=IFTI(fti);governance=gov;guardian=emergency;development=dev;
        epochEnd=(block.timestamp/1 hours+1)*1 hours;(nextBuilderMonth,)=Calendar.month(block.timestamp);
        for(uint256 i;i<31;i++){
            address who=genesis[i];require(who!=address(0)&&!members[who].exists,'genesis');
            members[who].exists=true;memberList.push(who);
            if(i>0){address parent=genesis[(i-1)/2];members[who].parent=parent;depth[who]=depth[parent]+1;if(i%2==1)members[parent].left=who;else members[parent].right=who;}
        }
        usd.forceApprove(fti,type(uint256).max);
    }
    function memberCount() external view returns(uint256){return memberList.length;}
    function jobCount() external view returns(uint256){return jobs.length;}
    function autoAccountCount() external view returns(uint256){return autoAccounts.length;}
    function builderAccountCount(uint256 month) external view returns(uint256){return builderAccounts[month].length;}
    function unitsOf(address who) external view returns(uint256){return members[who].units;}
    function rankOf(address who) external view returns(uint8){return members[who].rank;}
    function registered(address who) external view returns(bool){return members[who].exists;}
    /// @notice Cumulative gross-buy capacity uses current permanent rank and all paid units.
    ///         Builders alone receive the token's latched 10x-price milestone multiplier.
    ///         Rank/top-up/milestone increases grant only extra capacity; spent is never reset.
    function tokenBuyLimit(address who) public view returns(uint256){
        Member storage m=members[who];
        uint256[5] memory limits=[uint256(500),600,700,800,1000];
        uint256 multiplier=m.rank==0?1:token.priceMultiplier();
        return m.units*limits[m.rank]*1e18*multiplier;
    }
    function remainingTokenBuyAllowance(address who) public view returns(uint256){
        uint256 limit=tokenBuyLimit(who);uint256 spent=tokenBuySpent[who];
        return limit>spent?limit-spent:0;
    }
    /// @dev The bound token consumes permission atomically with the manual purchase. Reward auto-buys do not call this.
    function authorizeTokenBuy(address who,uint256 amount) external nonReentrant {
        require(msg.sender==address(token),'token only');
        require(members[who].units>0&&amount>0,'buy input');
        require(amount<=remainingTokenBuyAllowance(who),'allowance');
        tokenBuySpent[who]+=amount;
        emit TokenBuyAuthorized(who,amount,tokenBuySpent[who]);
    }
    function pause() external {require(msg.sender==guardian||msg.sender==governance,'role');_pause();}
    function unpause() external {require(msg.sender==governance,'governance');_unpause();}
    function register(address sponsor,uint256 units) external nonReentrant whenNotPaused {
        require(!members[msg.sender].exists&&members[sponsor].exists&&sponsor!=msg.sender,'registration');
        Member storage p=members[sponsor];require(p.right==address(0),'sponsor full');
        require(depth[sponsor]<MAX_DEPTH,'maximum tree depth');depth[msg.sender]=depth[sponsor]+1;
        members[msg.sender].exists=true;members[msg.sender].parent=sponsor;memberList.push(msg.sender);
        if(p.left==address(0))p.left=msg.sender;else p.right=msg.sender;
        _fund(msg.sender,units,true);emit Registered(msg.sender,sponsor,units);
    }
    function addUnits(uint256 units) external nonReentrant whenNotPaused {require(members[msg.sender].exists,'member');_fund(msg.sender,units,false);emit UnitsAdded(msg.sender,units);}
    function _fund(address who,uint256 units,bool newWallet) private {
        require(phase==0&&block.timestamp<epochEnd,'settlement required');require(units>0&&units<=1000000,'unit range');
        _backed();uint256 amount=units*UNIT;uint256 beforeBal=usd.balanceOf(address(this));uint256 beforeUser=usd.balanceOf(who);
        usd.safeTransferFrom(who,address(this),amount);require(usd.balanceOf(address(this))-beforeBal==amount&&beforeUser-usd.balanceOf(who)==amount,'unsupported USD');
        fundingSerial++;if(members[who].units==0)activatedAtSerial[who]=fundingSerial;
        members[who].units+=units;epochUnits+=units;unitsSinceSettlement+=units;pointPool+=units*90e18;
        pendingReward[development]+=units*1e18;totalPending+=units*1e18;
        (uint256 monthKey,)=Calendar.month(block.timestamp);uint256[4] memory portions=[uint256(16e17),12e17,8e17,4e17];
        for(uint256 i;i<4;i++)monthFunding[monthKey][i]+=units*portions[i];builderAccounted+=units*4e18;
        address parent=members[who].parent;uint256 d=depth[who];uint256 pointShare=d==0?0:units*90e18/d;uint256[4] memory shares;
        queuedPointCredit+=pointShare*d;retainedPointReserve+=units*90e18-pointShare*d;
        for(uint256 i;i<4;i++){shares[i]=d==0?0:units*portions[i]/d;queuedBuilderCredit+=shares[i]*d;retainedBuilderReserve+=units*portions[i]-shares[i]*d;}
        if(parent!=address(0))jobs.push(Job(who,parent,units,pointShare,shares,monthKey,fundingSerial));
        token.inject(units*5e18,newWallet);
        _backed();
    }
    function _touch(address who) private {if(!dirty[who]){dirty[who]=true;dirtyMembers[dirtyCount++]=who;}}
    function processVolume(uint256 steps) external nonReentrant {require(phase==0&&steps>0&&steps<=MAX_BATCH,'batch');
        for(uint256 i;i<steps&&jobCursor<jobs.length;i++){
            Job storage j=jobs[jobCursor];Member storage p=members[j.ancestor];
            bool left=p.left==j.child;require(left||p.right==j.child,'tree');
            // Eligibility is fixed at purchase serial, not at an arbitrary keeper execution time.
            bool active=activatedAtSerial[j.ancestor]>0&&activatedAtSerial[j.ancestor]<=j.serial;
            queuedPointCredit-=j.pointShare;
            if(active){
                if(left){p.carryL+=j.units;p.lifetimeL+=j.units;creditL[j.ancestor]+=j.pointShare;}
                else{p.carryR+=j.units;p.lifetimeR+=j.units;creditR[j.ancestor]+=j.pointShare;}
                assignedPointCredit+=j.pointShare;_touch(j.ancestor);
                if(!builderSeen[j.month][j.ancestor]){builderSeen[j.month][j.ancestor]=true;builderAccounts[j.month].push(j.ancestor);}
            }else retainedPointReserve+=j.pointShare;
            for(uint256 tier;tier<4;tier++){
                uint256 amount=j.builderShares[tier];queuedBuilderCredit-=amount;
                if(active){builderCredit[j.month][j.ancestor][tier]+=amount;assignedBuilderCredit+=amount;}
                else retainedBuilderReserve+=amount;
            }
            j.child=j.ancestor;j.ancestor=p.parent;if(j.ancestor==address(0))jobCursor++;
        }
    }
    function cap(uint8 rank,uint8 level) public pure returns(uint256){require(rank<5&&level<4,'cap');uint8[5][4] memory c=[[5,10,15,20,25],[5,10,12,16,20],[5,10,10,12,15],[5,10,10,10,10]];return c[level][rank];}
    function beginEpochClose() external nonReentrant {
        require(phase==0&&block.timestamp>=epochEnd&&jobCursor==jobs.length,'not ready');
        if(unitsSinceSettlement<5){_nextEpoch();return;}
        frozenMembers=dirtyCount;frozenLevel=protectionLevel;cursor=0;totalPaidPoints=0;allocated=0;matchedFunding=0;frozenPool=pointPool;phase=1;
        if(frozenMembers==0)_finishEpoch();
    }
    function processEpoch(uint256 batch) external nonReentrant {
        require(batch>0&&batch<=MAX_BATCH&&phase>0,'batch');
        uint256 end=cursor+batch;if(end>frozenMembers)end=frozenMembers;
            for(;cursor<end;cursor++){
                address who=dirtyMembers[cursor];Member storage m=members[who];uint256 raw=m.carryL<m.carryR?m.carryL:m.carryR;
                uint256 paid=raw<cap(m.rank,frozenLevel)?raw:cap(m.rank,frozenLevel);
                uint256 takenL=raw==0?0:Math.mulDiv(creditL[who],raw,m.carryL);
                uint256 takenR=raw==0?0:Math.mulDiv(creditR[who],raw,m.carryR);
                uint256 taken=takenL+takenR;uint256 budget=raw==0?0:Math.mulDiv(taken,paid,raw);
                uint256 reward=budget<paid*MAX_POINT_VALUE?budget:paid*MAX_POINT_VALUE;
                creditL[who]-=takenL;creditR[who]-=takenR;assignedPointCredit-=taken;retainedPointReserve+=taken-reward;
                m.carryL-=raw;m.carryR-=raw;paidPoints[epoch][who]=paid;totalPaidPoints+=paid;matchedFunding+=budget;
                autoSnapshot[epoch][who]=m.autoEnabled&&m.rank>0;
                uint256 automatic=autoSnapshot[epoch][who]?reward*5/100:0;
                pendingReward[who]+=reward-automatic;totalPending+=reward-automatic;pendingAuto[who]+=automatic;totalAuto+=automatic;
                if(automatic>0)_trackAuto(who);allocated+=reward;pointPool-=reward;settled[epoch][who]=true;dirty[who]=false;
                emit RewardAllocated(epoch,who,reward-automatic,automatic);
                uint256 lifetime=m.lifetimeL<m.lifetimeR?m.lifetimeL:m.lifetimeR;uint256[4] memory thresholds=[uint256(100),200,500,1000];
                if(m.units>0)for(uint256 r=m.rank;r<4;r++){if(lifetime>=thresholds[r]){m.rank=uint8(r+1);rankReachedAt[who][r]=uint64(epochEnd);}else break;}
            }
            if(cursor==frozenMembers)_finishEpoch();
    }
    function _finishEpoch() private {
        pointValue=totalPaidPoints==0?0:allocated/totalPaidPoints;
        if(totalPaidPoints>0){
            if(matchedFunding<MAX_POINT_VALUE*totalPaidPoints&&protectionLevel<3)protectionLevel++;
            else if(matchedFunding>MAX_POINT_VALUE*totalPaidPoints&&protectionLevel>0)protectionLevel--;
            unitsSinceSettlement=0;
        }
        // Reuse indexed slots: deleting an unbounded storage array would itself be an O(N) close.
        dirtyCount=0;emit EpochClosed(epoch,frozenPool,totalPaidPoints,pointValue,protectionLevel);_nextEpoch();
    }
    function _nextEpoch() private {lastClosedAt=(block.timestamp/1 hours)*1 hours;epoch++;epochEnd=(block.timestamp/1 hours+1)*1 hours;epochUnits=0;phase=0;cursor=0;}
    function setAutoBuy(bool enabled,uint256 maxPrice) external nonReentrant {require(phase==0,'settings frozen');require(members[msg.sender].exists,'member');require(!enabled||maxPrice>0,'price limit');members[msg.sender].autoEnabled=enabled;members[msg.sender].maxAutoPrice=maxPrice;if(enabled&&pendingAuto[msg.sender]>0)_trackAuto(msg.sender);else _removeAuto(msg.sender);}
    function _trackAuto(address who) private {if(autoIndex[who]==0){autoAccounts.push(who);autoIndex[who]=autoAccounts.length;}}
    function _removeAuto(address who) private {uint256 at=autoIndex[who];if(at==0)return;address last=autoAccounts[autoAccounts.length-1];autoAccounts[at-1]=last;autoIndex[last]=at;autoAccounts.pop();delete autoIndex[who];}
    function executeAuto(address who,uint256 amount) external nonReentrant {
        _backed();
        require(amount>0&&amount<=pendingAuto[who],'amount');
        require(members[who].autoEnabled,'auto disabled');
        // A keeper may not split someone else's reward into dust-sized lock tranches.
        // The beneficiary can still request a deliberate partial purchase.
        require(msg.sender==who||amount==pendingAuto[who],'partial auto owner only');
        uint256 maxPrice=members[who].maxAutoPrice;
        require(maxPrice>0&&token.price()<=maxPrice,'auto price limit');
        uint256 minimum=token.quoteBuy(amount);require(minimum>0,'dust');
        // Max price is the total USD paid per FTI received, including fees/curve impact.
        require(minimum>=Math.mulDiv(amount,1e18,maxPrice,Math.Rounding.Ceil),'auto execution price');
        pendingAuto[who]-=amount;totalAuto-=amount;
        if(pendingAuto[who]==0)_removeAuto(who);
        uint256 beforeBal=usd.balanceOf(address(this));uint256 minted=token.autoBuy(who,amount,minimum,block.timestamp);
        require(beforeBal-usd.balanceOf(address(this))==amount,'unsupported USD');_backed();emit AutoExecuted(who,amount,minted);
    }
    function releaseAutoToCash() external nonReentrant {uint256 amount=pendingAuto[msg.sender];pendingAuto[msg.sender]=0;totalAuto-=amount;pendingReward[msg.sender]+=amount;totalPending+=amount;_removeAuto(msg.sender);}
    function claim() external nonReentrant {_backed();uint256 amount=pendingReward[msg.sender];require(amount>0,'no reward');pendingReward[msg.sender]=0;totalPending-=amount;uint256 beforeBal=usd.balanceOf(address(this));uint256 beforeUser=usd.balanceOf(msg.sender);usd.safeTransfer(msg.sender,amount);require(beforeBal-usd.balanceOf(address(this))==amount&&usd.balanceOf(msg.sender)-beforeUser==amount,'unsupported USD');_backed();emit Claimed(msg.sender,amount);}
    function beginBuilderMonth() external nonReentrant {
        uint256 end=Calendar.endOf(nextBuilderMonth);require(monthPhase==0&&block.timestamp>=end&&lastClosedAt>=end,'month not ready');
        monthMembers=builderAccounts[nextBuilderMonth].length;monthCursor=0;monthPhase=1;
        for(uint256 p;p<4;p++){monthBalances[p]=monthFunding[nextBuilderMonth][p];monthFunding[nextBuilderMonth][p]=0;monthEligible[p]=0;monthPaid[p]=0;monthPay[p]=monthBalances[p]/5;}
        if(monthMembers==0)_finishBuilderMonth();
    }
    function _eligible(address who,uint256 p,uint256 end) private view returns(bool){uint256 at=rankReachedAt[who][p];return at>0&&at<=end&&!builderClaimed[who][p];}
    function processBuilderMonth(uint256 batch) external nonReentrant {
        require(monthPhase>0&&batch>0&&batch<=MAX_BATCH,'batch');uint256 end=monthCursor+batch;if(end>monthMembers)end=monthMembers;uint256 cutoff=Calendar.endOf(nextBuilderMonth);
        for(;monthCursor<end;monthCursor++){
            address who=builderAccounts[nextBuilderMonth][monthCursor];
            for(uint256 p;p<4;p++){
                uint256 credit=builderCredit[nextBuilderMonth][who][p];delete builderCredit[nextBuilderMonth][who][p];assignedBuilderCredit-=credit;
                uint256 pay;
                if(credit>0&&_eligible(who,p,cutoff)){
                    monthEligible[p]++;pay=credit<monthPay[p]?credit:monthPay[p];
                    if(pay>0){builderClaimed[who][p]=true;pendingReward[who]+=pay;totalPending+=pay;builderAccounted-=pay;monthPaid[p]+=pay;}
                }
                retainedBuilderReserve+=credit-pay;
            }
        }
        if(monthCursor==monthMembers)_finishBuilderMonth();
    }
    function _finishBuilderMonth() private {for(uint256 p;p<4;p++)builderCarry[p]+=monthBalances[p]-monthPaid[p];emit BuilderMonthClosed(nextBuilderMonth);nextBuilderMonth++;monthPhase=0;monthCursor=0;}
    function fundingAccounting() external view returns(uint256 pointCredits,uint256 pointBook,uint256 builderCredits,uint256 builderBook){return(queuedPointCredit+assignedPointCredit+retainedPointReserve,pointPool,queuedBuilderCredit+assignedBuilderCredit+retainedBuilderReserve,builderAccounted);}
    function _backed() private view {require(usd.balanceOf(address(this))>=pointPool+builderAccounted+totalPending+totalAuto,'reserve deficit');}
    function accounting() external view returns(uint256 actual,uint256 accounted){return(usd.balanceOf(address(this)),pointPool+builderAccounted+totalPending+totalAuto);}
    function rescue(address asset,address to,uint256 amount) external nonReentrant {require(msg.sender==governance&&asset!=address(usd)&&asset!=address(token),'protected');IERC20(asset).safeTransfer(to,amount);}
}

Governance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {TimelockController} from '@openzeppelin/contracts/governance/TimelockController.sol';
import {ReentrancyGuard} from '@openzeppelin/contracts/utils/ReentrancyGuard.sol';

/// @notice Fixed seven-owner council with five independent approvals required.
/// @dev Used as emergency guardian and sole proposer for the timelock.
///      The emergency path may activate redemption-only mode, but cannot transfer
///      the token reserve to an arbitrary administrator address.
contract Council is ReentrancyGuard {
    uint8 public constant OWNER_COUNT=7;
    uint8 public constant THRESHOLD=5;

    address[7] public owners;
    mapping(address=>bool) public isOwner;

    struct Proposal {address target;bytes data;bool executed;}
    Proposal[] private proposals;
    // A new tenure gets a new generation, including when an old key returns.
    mapping(address=>uint256) private ownerGeneration;
    mapping(uint256=>mapping(address=>uint256)) private approvalGeneration;

    event Proposed(uint256 indexed id,address indexed target,bytes data);
    event Approved(uint256 indexed id,address indexed owner);
    event Executed(uint256 indexed id);
    event OwnerReplaced(address indexed oldOwner,address indexed newOwner,uint256 indexed slot);

    constructor(address[7] memory initial){
        for(uint256 i;i<OWNER_COUNT;i++){
            require(initial[i]!=address(0)&&!isOwner[initial[i]],'owner');
            owners[i]=initial[i];
            isOwner[initial[i]]=true;
            ownerGeneration[initial[i]]=1;
        }
    }

    function count() external view returns(uint256){return proposals.length;}
    function proposal(uint256 id) external view returns(address,bytes memory,uint8,bool){
        Proposal storage p=proposals[id];
        return(p.target,p.data,_approvalCount(id),p.executed);
    }

    /// @notice Whether a current owner's current tenure approved this proposal.
    function approved(uint256 id,address owner) public view returns(bool){
        return isOwner[owner]&&approvalGeneration[id][owner]==ownerGeneration[owner];
    }

    function _approvalCount(uint256 id) private view returns(uint8 count_){
        for(uint256 i;i<OWNER_COUNT;i++)if(approved(id,owners[i]))count_++;
    }

    function propose(address target,bytes calldata data) external returns(uint256 id){
        require(isOwner[msg.sender]&&target.code.length>0,'owner/target');
        id=proposals.length;
        proposals.push(Proposal(target,data,false));
        approvalGeneration[id][msg.sender]=ownerGeneration[msg.sender];
        emit Proposed(id,target,data);
        emit Approved(id,msg.sender);
    }

    function approve(uint256 id) external {
        require(isOwner[msg.sender]&&!approved(id,msg.sender)&&!proposals[id].executed,'approval');
        approvalGeneration[id][msg.sender]=ownerGeneration[msg.sender];
        emit Approved(id,msg.sender);
    }

    function execute(uint256 id) external nonReentrant returns(bytes memory result){
        Proposal storage p=proposals[id];
        require(!p.executed&&_approvalCount(id)>=THRESHOLD,'threshold');
        p.executed=true;
        (bool ok,bytes memory ret)=p.target.call(p.data);
        if(!ok){assembly{revert(add(ret,32),mload(ret))}}
        emit Executed(id);
        return ret;
    }

    /// @notice Key rotation requires a normal 5-of-7 proposal targeting the Council itself.
    function replaceOwner(address oldOwner,address newOwner) external {
        require(msg.sender==address(this),'self only');
        require(oldOwner!=address(0)&&newOwner!=address(0)&&isOwner[oldOwner]&&!isOwner[newOwner],'owner');
        uint256 slot=type(uint256).max;
        for(uint256 i;i<OWNER_COUNT;i++)if(owners[i]==oldOwner){slot=i;break;}
        require(slot<OWNER_COUNT,'slot');
        owners[slot]=newOwner;
        isOwner[oldOwner]=false;
        isOwner[newOwner]=true;
        ownerGeneration[newOwner]++;
        emit OwnerReplaced(oldOwner,newOwner,slot);
    }
}

/// @notice Normal governance operations retain the existing 72-hour initial timelock.
/// @dev Emergency redemption-only activation is performed by the 5-of-7 Council directly.
contract FTITimelock is TimelockController {
    uint256 public constant FIXED_MIN_DELAY=72 hours;
    constructor(address council)
        TimelockController(FIXED_MIN_DELAY,_one(council),_one(address(0)),address(0))
    {}

    /// @notice V2 governance delay cannot be reduced after deployment.
    function updateDelay(uint256) external pure override {
        revert('fixed 72h delay');
    }

    function _one(address a) private pure returns(address[] memory r){
        r=new address[](1);
        r[0]=a;
    }
}

